#!/usr/bin/env bash
# =========================================================================
# ServerTools v2.0.0-dev — single-file build
# Generated from src/ by build.sh — DO NOT EDIT THIS FILE DIRECTLY.
# https://github.com/Sir-Adnan/server-tools
# =========================================================================

# ------------------------- src/00-header.sh -------------------------
# ============================================================================
# src/00-header.sh — strict mode, global constants, error trap.
# This file MUST be first in the build order (see build.sh SOURCES).
# ============================================================================

set -Eeuo pipefail
IFS=$'\n\t'

if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4))); then
  printf 'ServerTools requires bash >= 4.4 (found %s)\n' "${BASH_VERSION}" >&2
  exit 1
fi

readonly ST_NAME="ServerTools"
readonly ST_VERSION="2.0.0-dev"
readonly ST_REPO_URL="https://github.com/Sir-Adnan/server-tools"

# Filesystem layout (FHS): config in /etc, state and backups in /var/lib,
# log in /var/log. Nothing is ever written to /tmp (predictable names in
# world-writable directories are a symlink-attack risk for a root tool).
readonly ST_ETC_DIR="/etc/server-tools"
readonly ST_CONFIG_FILE="${ST_ETC_DIR}/config"
readonly ST_LIB_DIR="/var/lib/server-tools"
readonly ST_BACKUP_DIR="${ST_LIB_DIR}/backups"
readonly ST_ORIGINAL_DIR="${ST_BACKUP_DIR}/original"
readonly ST_MANIFEST_FILE="${ST_LIB_DIR}/manifest.tsv"

ST_RUN_ID="$(date +%Y%m%d-%H%M%S)"
readonly ST_RUN_ID
readonly ST_RUN_BACKUP_DIR="${ST_BACKUP_DIR}/runs/${ST_RUN_ID}"

# Runtime flags — may be flipped by CLI arguments before initialisation.
ST_OPT_DEBUG=0
ST_OPT_NO_COLOR=0
ST_OPT_BATCH=0

on_unhandled_error() {
  local exit_code="$1" line="$2" command="$3"
  local msg="unhandled failure (exit=${exit_code}) at line ${line}: ${command}"
  if declare -F log_error >/dev/null 2>&1; then
    log_error "$msg"
  else
    printf '\n[%s] %s\n' "$ST_NAME" "$msg" >&2
  fi
}
trap 'on_unhandled_error "$?" "$LINENO" "$BASH_COMMAND"' ERR

# ------------------------- src/core/colors.sh -------------------------
# ============================================================================
# core/colors.sh — terminal capability detection and the UI palette.
#
# Rules:
#   - Color labels/titles only, never values (readable on light AND dark
#     terminals — no assumption about the user's background color).
#   - Honour NO_COLOR (https://no-color.org), non-tty output, and TERM=dumb.
#   - Unicode (box drawing) only when the locale advertises UTF-8.
# ============================================================================

ST_TTY=0
ST_UTF8=0

C_RESET='' C_BOLD='' C_DIM=''
C_TITLE='' C_KEY='' C_ACCENT='' C_LINE='' C_MUTED=''
C_OK='' C_WARN='' C_ERR=''

ui_detect_terminal() {
  [[ -t 1 ]] && ST_TTY=1

  case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]-8* | *[Uu][Tt][Ff]8*) ST_UTF8=1 ;;
  esac

  local want_color=$ST_TTY
  [[ -n ${NO_COLOR:-} ]] && want_color=0
  [[ ${TERM:-dumb} == dumb ]] && want_color=0
  ((ST_OPT_NO_COLOR)) && want_color=0
  ((want_color)) || return 0

  C_RESET=$'\033[0m'
  # C_BOLD/C_DIM: kept so the palette is complete for future modules.
  # shellcheck disable=SC2034
  C_BOLD=$'\033[1m'
  # shellcheck disable=SC2034
  C_DIM=$'\033[2m'

  # Classic (non-bright) ANSI colors — stable across terminal themes.
  C_TITLE=$'\033[1;36m'  # bold cyan   — screen titles, banner
  C_KEY=$'\033[1;34m'    # bold blue   — menu keys, kv labels
  C_ACCENT=$'\033[1;35m' # bold magenta — highlights
  C_LINE=$'\033[0;34m'   # blue        — separators
  C_MUTED=$'\033[2m'     # dim         — hints, secondary text
  C_OK=$'\033[1;32m'
  C_WARN=$'\033[1;33m'
  C_ERR=$'\033[1;31m'
  return 0
}

# ------------------------- src/core/log.sh -------------------------
# ============================================================================
# core/log.sh — leveled logging with size-based rotation.
# Primary target /var/log/server-tools.log, falling back to the state dir.
# ============================================================================

ST_LOG_FILE="/var/log/server-tools.log"
readonly ST_LOG_MAX_BYTES=$((2 * 1024 * 1024))

log_init() {
  if ! touch "$ST_LOG_FILE" 2>/dev/null; then
    mkdir -p "$ST_LIB_DIR"
    ST_LOG_FILE="${ST_LIB_DIR}/server-tools.log"
    touch "$ST_LOG_FILE"
  fi
}

_log_rotate_if_needed() {
  [[ -f $ST_LOG_FILE ]] || return 0
  local size
  size="$(wc -c <"$ST_LOG_FILE" 2>/dev/null)" || size=0
  if ((size > ST_LOG_MAX_BYTES)); then
    mv -f "$ST_LOG_FILE" "${ST_LOG_FILE}.1"
    : >"$ST_LOG_FILE"
  fi
}

# _log LEVEL MESSAGE... — appends to the log file when it is writable
# (before log_init, or as non-root, messages go to the console only).
_log() {
  local level="$1"
  shift
  [[ -w $ST_LOG_FILE ]] || return 0
  _log_rotate_if_needed
  printf '[%s] [%-5s] %s\n' "$(date '+%F %T')" "$level" "$*" >>"$ST_LOG_FILE"
}

log_debug() {
  ((ST_OPT_DEBUG)) || return 0
  _log DEBUG "$@"
  printf '%bDEBUG%b %s\n' "$C_MUTED" "$C_RESET" "$*" >&2
}

log_info() { _log INFO "$@"; }

log_warn() {
  _log WARN "$@"
  printf '%bWARN%b  %s\n' "$C_WARN" "$C_RESET" "$*" >&2
}

log_error() {
  _log ERROR "$@"
  printf '%bERROR%b %s\n' "$C_ERR" "$C_RESET" "$*" >&2
}

# die MESSAGE — log the error and exit with failure.
die() {
  log_error "$@"
  exit 1
}

# ------------------------- src/core/ui.sh -------------------------
# ============================================================================
# core/ui.sh — reusable terminal UI kit: rules, titles, key/value rows,
# menu items, confirm/pause. Pure bash + printf, no external UI tools.
# ============================================================================

ui_width() {
  local cols
  cols="$(tput cols 2>/dev/null)" || cols=90
  [[ $cols =~ ^[0-9]+$ ]] || cols=90
  ((cols < 70)) && cols=70
  ((cols > 100)) && cols=100
  printf '%s' "$cols"
}

# ui_repeat CHAR COUNT — prints CHAR repeated COUNT times.
ui_repeat() {
  local pad
  printf -v pad '%*s' "$2" ''
  printf '%s' "${pad// /$1}"
}

ui_hr() {
  local ch='-'
  ((ST_UTF8)) && ch='─'
  printf '%s%s%s\n' "$C_LINE" "$(ui_repeat "$ch" "$(ui_width)")" "$C_RESET"
}

ui_hr_heavy() {
  local ch='='
  ((ST_UTF8)) && ch='═'
  printf '%s%s%s\n' "$C_LINE" "$(ui_repeat "$ch" "$(ui_width)")" "$C_RESET"
}

# ui_center TEXT [COLOR] — center TEXT within the terminal width.
ui_center() {
  local text="$1" color="${2:-}"
  local width pad
  width="$(ui_width)"
  pad=0
  ((${#text} < width)) && pad=$(((width - ${#text}) / 2))
  printf '%*s%s%s%s\n' "$pad" '' "$color" "$text" "${color:+$C_RESET}"
}

ui_title() {
  ui_hr
  ui_center "$1" "$C_TITLE"
  ui_hr
}

ui_section() {
  printf '%s[%s]%s\n' "$C_TITLE" "$1" "$C_RESET"
}

# ui_kv KEY VALUE — colored label, plain value.
ui_kv() {
  printf '  %s%-18s%s %s\n' "$C_KEY" "$1:" "$C_RESET" "$2"
}

# ui_menu_item KEY LABEL [HINT]
ui_menu_item() {
  printf '  %s[%s]%s %-20s %s%s%s\n' "$C_KEY" "$1" "$C_RESET" "$2" "$C_MUTED" "${3:-}" "$C_RESET"
}

ui_logo() {
  # clear can fail on TERM=dumb / weird terminals — purely cosmetic.
  ((ST_OPT_BATCH)) || clear 2>/dev/null || true
  printf '%s' "$C_TITLE"
  cat <<'LOGO'
  ____                          _____           _
 / ___|  ___ _ ____   _____ _ _|_   _|__   ___ | |___
 \___ \ / _ \ '__\ \ / / _ \ '__|| |/ _ \ / _ \| / __|
  ___) |  __/ |   \ V /  __/ |   | | (_) | (_) | \__ \
 |____/ \___|_|    \_/ \___|_|   |_|\___/ \___/|_|___/
LOGO
  printf '%s' "$C_RESET"
  ui_center "v${ST_VERSION} — server optimization toolkit by @UnknownZero" "$C_MUTED"
  ui_hr_heavy
}

# ui_confirm PROMPT — returns 0 only on an explicit yes.
ui_confirm() {
  local reply
  read -rp "$1 [y/N]: " reply || return 1
  [[ ${reply,,} == y || ${reply,,} == yes ]]
}

# ui_confirm_yes PROMPT — like ui_confirm but Enter means yes.
ui_confirm_yes() {
  local reply
  read -rp "$1 [Y/n]: " reply || return 1
  [[ -z $reply || ${reply,,} == y || ${reply,,} == yes ]]
}

ui_pause() {
  ((ST_OPT_BATCH)) && return 0
  [[ -t 0 ]] || return 0
  # EOF from a closed stdin is not an error here.
  read -rsn1 -p "Press any key to continue..." || true
  printf '\n'
}

# ui_todo FEATURE — honest placeholder for milestones not yet implemented.
ui_todo() {
  printf '%s[planned]%s %s is not implemented yet — it arrives in an upcoming v2 milestone.\n' \
    "$C_WARN" "$C_RESET" "$1"
  printf '%sRoadmap: %s#روادمپ / docs in the repository.%s\n' "$C_MUTED" "$ST_REPO_URL" "$C_RESET"
  ui_pause
}

# ------------------------- src/core/utils.sh -------------------------
# ============================================================================
# core/utils.sh — small dependency-free helpers: command/root checks,
# OS facts (from /proc and /etc/os-release), network facts, cached public IP.
# ============================================================================

has_cmd() { command -v "$1" >/dev/null 2>&1; }

require_root() {
  ((EUID == 0)) || die "This tool must be run as root (try: sudo -i)."
}

os_pretty_name() {
  local name=''
  if [[ -r /etc/os-release ]]; then
    name="$(. /etc/os-release 2>/dev/null && printf '%s' "${PRETTY_NAME:-}")" || name=''
  fi
  printf '%s' "${name:-unknown}"
}

kernel_release() { uname -r 2>/dev/null || printf 'unknown'; }

kernel_base() {
  local rel
  rel="$(kernel_release)"
  printf '%s' "${rel%%-*}"
}

detect_virt() {
  local virt=''
  if has_cmd systemd-detect-virt; then
    # Exit code 1 simply means "not virtualised"; the answer is on stdout.
    virt="$(systemd-detect-virt 2>/dev/null)" || true
  fi
  printf '%s' "${virt:-unknown}"
}

mem_total_mb() {
  awk '/^MemTotal:/ {print int($2 / 1024); exit}' /proc/meminfo 2>/dev/null || printf '0'
}

cpu_cores() {
  if has_cmd nproc; then
    nproc
  else
    grep -c '^processor' /proc/cpuinfo 2>/dev/null || printf '1'
  fi
}

cpu_model() {
  local model
  model="$(awk -F': *' '/^(model name|Model)/ {print $2; exit}' /proc/cpuinfo 2>/dev/null)" || model=''
  printf '%s' "${model:-unknown}"
}

uptime_pretty() {
  local secs
  secs="$(cut -d. -f1 /proc/uptime 2>/dev/null)" || secs=''
  [[ $secs =~ ^[0-9]+$ ]] || {
    printf 'unknown'
    return 0
  }
  printf '%dd %dh %dm' $((secs / 86400)) $((secs % 86400 / 3600)) $((secs % 3600 / 60))
}

load_avg() {
  cut -d' ' -f1-3 /proc/loadavg 2>/dev/null || printf 'unknown'
}

# ver_ge A B — true when dotted version A >= B.
ver_ge() {
  [[ "$(printf '%s\n' "$1" "$2" | sort -V | head -n1)" == "$2" ]]
}

is_valid_ipv4() {
  local ip="$1" octet
  [[ $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
  local IFS='.'
  for octet in $ip; do
    ((octet <= 255)) || return 1
  done
  return 0
}

net_default_iface() {
  has_cmd ip || return 0
  ip route show default 2>/dev/null |
    awk '{for (i = 1; i < NF; i++) if ($i == "dev") {print $(i + 1); exit}}'
}

net_default_gw() {
  has_cmd ip || return 0
  ip route show default 2>/dev/null |
    awk '{for (i = 1; i < NF; i++) if ($i == "via") {print $(i + 1); exit}}'
}

# pkg_install PACKAGE — caller must already have the user's consent
# (CLAUDE.md rule 1: nothing is installed silently). Output goes to the log.
ST_PKG_INDEX_UPDATED=0

pkg_install() {
  local pkg="$1"
  if has_cmd apt-get; then
    export DEBIAN_FRONTEND=noninteractive
    if ((ST_PKG_INDEX_UPDATED == 0)); then
      apt-get update -qq >>"$ST_LOG_FILE" 2>&1 ||
        log_warn "apt index update failed — trying the install anyway."
      ST_PKG_INDEX_UPDATED=1
    fi
    apt-get install -y -qq "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd dnf; then
    dnf install -y "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd yum; then
    yum install -y "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd pacman; then
    pacman -Sy --noconfirm "$pkg" >>"$ST_LOG_FILE" 2>&1
  else
    log_error "No supported package manager found to install ${pkg}."
    return 1
  fi
}

# sysctl_get KEY — current value or "?" when unavailable.
sysctl_get() {
  local value
  if has_cmd sysctl; then
    value="$(sysctl -n "$1" 2>/dev/null)" || value=''
  fi
  printf '%s' "${value:-?}"
}

# --- Public IP (fetched once per process, then cached — the menu redraws
# --- must never block on network calls).
ST_CACHE_IP4=''
ST_CACHE_IP6=''

_net_fetch() { # _net_fetch 4|6 URL
  has_cmd curl || return 1
  # Short timeout: this runs during the first dashboard render and must
  # never make the menu feel stuck on servers with broken connectivity.
  curl "-$1" -fsS --max-time 2 "$2" 2>/dev/null | tr -d '[:space:]'
}

net_public_ip4() {
  if [[ -z $ST_CACHE_IP4 ]]; then
    local ip='' url
    for url in 'https://api.ipify.org' 'https://ifconfig.me/ip'; do
      ip="$(_net_fetch 4 "$url")" || ip=''
      is_valid_ipv4 "$ip" && break
      ip=''
    done
    if [[ -z $ip ]] && has_cmd ip; then
      ip="$(ip -4 addr show scope global 2>/dev/null |
        awk '/inet / {sub(/\/.*/, "", $2); print $2; exit}')" || ip=''
    fi
    ST_CACHE_IP4="${ip:-N/A}"
  fi
  printf '%s' "$ST_CACHE_IP4"
}

net_public_ip6() {
  if [[ -z $ST_CACHE_IP6 ]]; then
    local ip='' url
    for url in 'https://api64.ipify.org' 'https://ifconfig.me/ip'; do
      ip="$(_net_fetch 6 "$url")" || ip=''
      [[ $ip == *:* ]] && break
      ip=''
    done
    if [[ -z $ip ]] && has_cmd ip; then
      ip="$(ip -6 addr show scope global 2>/dev/null |
        awk '/inet6 / {sub(/\/.*/, "", $2); print $2; exit}')" || ip=''
    fi
    ST_CACHE_IP6="${ip:-N/A}"
  fi
  printf '%s' "$ST_CACHE_IP6"
}

# ------------------------- src/core/state.sh -------------------------
# ============================================================================
# core/state.sh — persistent user config (key=value) and the change manifest.
#
# The manifest is the source of truth for rollback: every file the tool
# creates or modifies gets one TSV row (see docs/ROLLBACK.md).
# ============================================================================

declare -A ST_CONFIG=()

state_init() {
  mkdir -p "$ST_ETC_DIR" "$ST_LIB_DIR" "$ST_BACKUP_DIR"
  if [[ ! -f $ST_MANIFEST_FILE ]]; then
    printf '# timestamp\trun_id\taction\ttarget\n' >"$ST_MANIFEST_FILE"
  fi
}

config_load() {
  ST_CONFIG=()
  [[ -f $ST_CONFIG_FILE ]] || return 0
  local key value
  while IFS='=' read -r key value; do
    [[ -z $key || $key == \#* ]] && continue
    ST_CONFIG[$key]="$value"
  done <"$ST_CONFIG_FILE"
}

config_get() { # config_get KEY [DEFAULT]
  printf '%s' "${ST_CONFIG[$1]:-${2:-}}"
}

config_set() { # config_set KEY VALUE — updates memory and persists.
  ST_CONFIG[$1]="$2"
  config_save
}

config_save() {
  mkdir -p "$ST_ETC_DIR"
  local tmp="${ST_CONFIG_FILE}.tmp" key
  {
    printf '# %s configuration — generated; editing by hand is fine.\n' "$ST_NAME"
    for key in "${!ST_CONFIG[@]}"; do
      printf '%s=%s\n' "$key" "${ST_CONFIG[$key]}"
    done | sort
  } >"$tmp"
  mv -f "$tmp" "$ST_CONFIG_FILE"
}

# manifest_add ACTION TARGET — ACTION is "created" or "modified".
manifest_add() {
  printf '%s\t%s\t%s\t%s\n' "$(date '+%F %T')" "$ST_RUN_ID" "$1" "$2" >>"$ST_MANIFEST_FILE"
}

manifest_entry_count() {
  [[ -f $ST_MANIFEST_FILE ]] || {
    printf '0'
    return 0
  }
  awk 'NR > 1' "$ST_MANIFEST_FILE" | wc -l | tr -d '[:space:]'
}

# manifest_latest_run — most recent run id that recorded changes (empty if none).
manifest_latest_run() {
  [[ -f $ST_MANIFEST_FILE ]] || return 0
  awk -F'\t' 'NR > 1 {print $2}' "$ST_MANIFEST_FILE" | sort -u | tail -n1
}

# ------------------------- src/core/backup.sh -------------------------
# ============================================================================
# core/backup.sh — track-before-touch backups and manifest-driven rollback.
#
# Contract (see CLAUDE.md rule 3): call `st_track_file PATH` BEFORE creating
# or modifying PATH. This yields:
#   - a pristine copy under original/ the first time the tool ever touches
#     the file (never overwritten afterwards),
#   - a per-run copy under runs/<run-id>/ (mirror of the absolute path),
#   - a manifest row ("modified" or "created") for rollback.
# ============================================================================

st_track_file() {
  local path="$1"
  mkdir -p "$ST_RUN_BACKUP_DIR"
  if [[ -e $path || -L $path ]]; then
    if [[ ! -e ${ST_ORIGINAL_DIR}${path} && ! -L ${ST_ORIGINAL_DIR}${path} ]]; then
      mkdir -p "${ST_ORIGINAL_DIR}$(dirname "$path")"
      cp -a "$path" "${ST_ORIGINAL_DIR}${path}"
    fi
    mkdir -p "${ST_RUN_BACKUP_DIR}$(dirname "$path")"
    cp -a "$path" "${ST_RUN_BACKUP_DIR}${path}"
    manifest_add modified "$path"
    log_debug "tracked (modified): $path"
  else
    manifest_add created "$path"
    log_debug "tracked (created): $path"
  fi
}

# rollback_latest — revert everything recorded by the most recent run,
# newest change first. Files "created" by that run are removed; "modified"
# files are restored from the run backup.
rollback_latest() {
  local run
  run="$(manifest_latest_run)"
  if [[ -z $run ]]; then
    log_warn "No recorded changes — nothing to roll back."
    return 0
  fi

  local src="${ST_BACKUP_DIR}/runs/${run}"
  local action target restored=0 removed=0 missing=0 sysctl_touched=0 units_touched=0
  while IFS=$'\t' read -r action target; do
    case "$action" in
      unit)
        # A systemd unit this run enabled: disable it (stop included) so no
        # dangling .wants symlink survives after its file is removed below.
        if has_cmd systemctl; then
          systemctl disable --now "$target" >/dev/null 2>>"$ST_LOG_FILE" ||
            log_warn "Could not disable unit ${target}."
          units_touched=1
        fi
        ;;
      modified)
        if [[ -e ${src}${target} || -L ${src}${target} ]]; then
          cp -a "${src}${target}" "$target"
          restored=$((restored + 1))
          [[ $target == /etc/sysctl.d/* || $target == /etc/sysctl.conf ]] && sysctl_touched=1
        else
          log_warn "Backup missing for ${target} — skipped."
          missing=$((missing + 1))
        fi
        ;;
      created)
        # Never delete an active swap file out from under the kernel.
        if [[ -r /proc/swaps ]] && grep -q "^${target}[[:space:]]" /proc/swaps 2>/dev/null; then
          if ! swapoff "$target" 2>>"$ST_LOG_FILE"; then
            log_warn "Cannot swapoff ${target} — left in place."
            missing=$((missing + 1))
            continue
          fi
        fi
        rm -f "$target"
        removed=$((removed + 1))
        [[ $target == /etc/sysctl.d/* ]] && sysctl_touched=1
        ;;
    esac
  done < <(awk -F'\t' -v run="$run" 'NR > 1 && $2 == run {print $3 "\t" $4}' "$ST_MANIFEST_FILE" | tac)

  if ((units_touched)) && has_cmd systemctl; then
    systemctl daemon-reload 2>>"$ST_LOG_FILE" ||
      log_warn "daemon-reload after rollback failed."
  fi
  if ((sysctl_touched)) && has_cmd sysctl; then
    sysctl --system >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "sysctl reload after rollback reported errors (see log)."
  fi

  log_info "Rollback of run ${run}: ${restored} restored, ${removed} removed, ${missing} missing."
  printf '%sRollback of run %s:%s %d file(s) restored, %d removed' \
    "$C_OK" "$run" "$C_RESET" "$restored" "$removed"
  ((missing > 0)) && printf ', %s%d backup(s) missing%s' "$C_WARN" "$missing" "$C_RESET"
  printf '\n'
  printf '%sNote:%s runtime state (loaded sysctl values, running services) is not\n' "$C_MUTED" "$C_RESET"
  printf '%sreverted automatically — a reboot guarantees a clean slate.%s\n' "$C_MUTED" "$C_RESET"
  return 0
}

# ------------------------- src/modules/detect.sh -------------------------
# ============================================================================
# modules/detect.sh — detect which VPN workload runs on this server.
#
# A server is usually EITHER a panel (Marzban/Pasarguard dashboard, no VPN
# traffic) OR a node (marzban-node / pg-node — the Xray core carrying user
# traffic) OR a WireGuard host. Detection picks the workload layer that the
# optimizer will suggest; the base layer always covers the whole server.
# ============================================================================

ST_DETECTED=()

_detect_add() { # _detect_add TAG — append once.
  local tag="$1" existing
  for existing in "${ST_DETECTED[@]-}"; do
    [[ $existing == "$tag" ]] && return 0
  done
  ST_DETECTED+=("$tag")
}

_detect_match() { # _detect_match HAYSTACK REGEX
  [[ -n $1 ]] && grep -qiE "$2" <<<"$1"
}

detect_stack() {
  ST_DETECTED=()

  # Containers from docker AND podman — some hosts run nodes under podman.
  local containers=''
  if has_cmd docker; then
    containers="$(docker ps --format '{{.Names}} {{.Image}}' 2>/dev/null)" || containers=''
  fi
  if has_cmd podman; then
    local podman_ps
    podman_ps="$(podman ps --format '{{.Names}} {{.Image}}' 2>/dev/null)" || podman_ps=''
    containers="${containers}${containers:+$'\n'}${podman_ps}"
  fi

  # Nodes first — "marzban" alone must not swallow "marzban-node".
  _detect_match "$containers" 'marzban[-_]node' && _detect_add 'marzban-node'
  _detect_match "$containers" 'pg[-_]node|pasarguard' && _detect_add 'pg-node'
  if _detect_match "$containers" 'marzban|marzneshin' &&
    ! _detect_match "$containers" 'marzban[-_]node'; then
    _detect_add 'marzban-panel'
  fi
  _detect_match "$containers" 'hiddify' && _detect_add 'hiddify'
  _detect_match "$containers" '3x-ui|x-ui' && _detect_add 'x-ui'
  _detect_match "$containers" 'sing-?box' && _detect_add 'sing-box'
  _detect_match "$containers" 'hysteria' && _detect_add 'hysteria'
  _detect_match "$containers" 'openvpn' && _detect_add 'openvpn'
  _detect_match "$containers" 'wgdashboard|wg-easy' && _detect_add 'wg-dashboard'

  if has_cmd systemctl; then
    systemctl is-active --quiet x-ui 2>/dev/null && _detect_add 'x-ui'
    systemctl is-active --quiet xray 2>/dev/null && _detect_add 'xray'
    systemctl is-active --quiet sing-box 2>/dev/null && _detect_add 'sing-box'
    systemctl is-active --quiet hysteria-server 2>/dev/null && _detect_add 'hysteria'
    systemctl is-active --quiet openvpn 2>/dev/null && _detect_add 'openvpn'
  fi

  if has_cmd wg && [[ -n "$(wg show interfaces 2>/dev/null)" ]]; then
    _detect_add 'wireguard'
  fi

  log_debug "detected workloads: ${ST_DETECTED[*]-none}"
  return 0
}

detect_summary() {
  if ((${#ST_DETECTED[@]} == 0)); then
    printf 'none (general server)'
  else
    local IFS=', '
    printf '%s' "${ST_DETECTED[*]}"
  fi
}

# ------------------------- src/modules/sysinfo.sh -------------------------
# ============================================================================
# modules/sysinfo.sh — the System Status report (menu option and --status).
# Reads /proc directly where possible so it works even in minimal containers.
# ============================================================================

_meminfo_kb() { # _meminfo_kb FIELD — e.g. MemTotal
  awk -v field="$1:" '$1 == field {print $2; exit}' /proc/meminfo 2>/dev/null || printf '0'
}

_disk_root_summary() {
  if has_cmd df; then
    df -h / 2>/dev/null | awk 'NR == 2 {printf "%s used / %s (%s)", $3, $2, $5}'
  else
    printf 'unknown'
  fi
}

show_status() {
  ui_logo
  ui_title "System Status"

  ui_section "System"
  ui_kv "OS" "$(os_pretty_name)"
  ui_kv "Kernel" "$(kernel_release)"
  ui_kv "Virtualization" "$(detect_virt)"
  ui_kv "Uptime" "$(uptime_pretty)"
  ui_hr

  ui_section "CPU"
  ui_kv "Model" "$(cpu_model)"
  ui_kv "Cores" "$(cpu_cores)"
  ui_kv "Load (1/5/15m)" "$(load_avg)"
  ui_hr

  ui_section "Memory"
  local mem_total_kb mem_avail_kb swap_total_kb swap_free_kb
  mem_total_kb="$(_meminfo_kb MemTotal)"
  mem_avail_kb="$(_meminfo_kb MemAvailable)"
  swap_total_kb="$(_meminfo_kb SwapTotal)"
  swap_free_kb="$(_meminfo_kb SwapFree)"
  ui_kv "RAM" "$((mem_total_kb / 1024)) MB total, $((mem_avail_kb / 1024)) MB available"
  if ((swap_total_kb > 0)); then
    ui_kv "Swap" "$(((swap_total_kb - swap_free_kb) / 1024)) MB used / $((swap_total_kb / 1024)) MB"
  else
    ui_kv "Swap" "disabled"
  fi
  ui_kv "Disk (/)" "$(_disk_root_summary)"
  ui_hr

  ui_section "Network"
  ui_kv "Default IF" "$(net_default_iface || true)"
  ui_kv "Gateway" "$(net_default_gw || true)"
  ui_kv "Public IPv4" "$(net_public_ip4)"
  ui_kv "Public IPv6" "$(net_public_ip6)"
  ui_hr

  ui_section "TCP / Tuning"
  local cc
  cc="$(sysctl_get net.ipv4.tcp_congestion_control)"
  if [[ $cc == bbr* ]]; then
    ui_kv "Congestion" "${cc} (BBR enabled)"
  else
    ui_kv "Congestion" "${cc}"
  fi
  ui_kv "Qdisc" "$(sysctl_get net.core.default_qdisc)"
  ui_kv "MTU probing" "$(sysctl_get net.ipv4.tcp_mtu_probing)"
  ui_kv "IPv4 forward" "$(sysctl_get net.ipv4.ip_forward)"
  ui_kv "IPv6 forward" "$(sysctl_get net.ipv6.conf.all.forwarding)"
  ui_hr

  ui_section "ServerTools"
  ui_kv "Detected" "$(detect_summary)"
  ui_kv "Recorded changes" "$(manifest_entry_count)"
  ui_kv "Log file" "$ST_LOG_FILE"
  ui_hr_heavy

  ui_pause
}

# ------------------------- src/modules/profile.sh -------------------------
# ============================================================================
# modules/profile.sh — layered profile resolution and capacity tiers.
# Implements docs/PROFILES.md: the base layer ALWAYS covers the whole server;
# the workload profile only decides the specialised extras on top.
# ============================================================================

ST_PROFILE='general'
ST_PROFILE_SOURCE='default'

ST_TIER=''
ST_TIER_USERS=''
ST_SOMAXCONN=0
ST_NETDEV_BACKLOG=0
ST_BUF_MB=0
ST_CONNTRACK=0

profile_resolve_auto() {
  local detected=" ${ST_DETECTED[*]-} "
  ST_PROFILE_SOURCE='auto-detected'
  if [[ $detected == *'marzban-node'* || $detected == *'pg-node'* ||
    $detected == *'xray'* || $detected == *'x-ui'* || $detected == *'hiddify'* ||
    $detected == *'sing-box'* || $detected == *'hysteria'* || $detected == *'openvpn'* ]]; then
    ST_PROFILE='vpn-node'
  elif [[ $detected == *'wireguard'* || $detected == *'wg-dashboard'* ]]; then
    ST_PROFILE='wireguard'
  elif [[ $detected == *'marzban-panel'* ]]; then
    ST_PROFILE='panel'
  else
    ST_PROFILE='general'
    ST_PROFILE_SOURCE='nothing detected'
  fi
}

# profile_wants_forwarding — vpn workloads route user traffic.
profile_wants_forwarding() {
  [[ $ST_PROFILE == vpn-node || $ST_PROFILE == wireguard || $ST_PROFILE == full ]]
}

tier_set() {
  ST_TIER="$1"
  case "$1" in
    S) ST_TIER_USERS='~1k' ST_SOMAXCONN=8192 ST_NETDEV_BACKLOG=16384 ST_BUF_MB=8 ST_CONNTRACK=65536 ;;
    M) ST_TIER_USERS='~10k' ST_SOMAXCONN=16384 ST_NETDEV_BACKLOG=32768 ST_BUF_MB=16 ST_CONNTRACK=262144 ;;
    L) ST_TIER_USERS='~100k' ST_SOMAXCONN=32768 ST_NETDEV_BACKLOG=65536 ST_BUF_MB=32 ST_CONNTRACK=1048576 ;;
    XL) ST_TIER_USERS='100k+' ST_SOMAXCONN=65535 ST_NETDEV_BACKLOG=65536 ST_BUF_MB=64 ST_CONNTRACK=2097152 ;;
    *) tier_set S ;;
  esac
}

# tier_compute — pick from RAM; the capacity_tier config key overrides.
tier_compute() {
  local override ram_mb
  override="$(config_get capacity_tier auto)"
  case "$override" in
    S | M | L | XL)
      tier_set "$override"
      return 0
      ;;
  esac

  ram_mb="$(mem_total_mb)"
  if ((ram_mb <= 1536)); then
    tier_set S
  elif ((ram_mb <= 6144)); then
    tier_set M
  elif ((ram_mb <= 24576)); then
    tier_set L
  else
    tier_set XL
  fi

  # A panel host never needs an L/XL conntrack table (docs/PROFILES.md) —
  # its RAM is better left to the database.
  if [[ $ST_PROFILE == panel && ($ST_TIER == L || $ST_TIER == XL) ]]; then
    tier_set M
  fi

  capacity_apply_users
  return 0
}

tier_conntrack_ram_mb() {
  # ~300 bytes per conntrack entry, worst case (table full).
  printf '%d' $((ST_CONNTRACK * 300 / 1048576))
}

# --- User-based capacity model -------------------------------------------
# Conntrack demand follows the ACTIVE USER COUNT, not RAM: ~24 flows per
# online user × 1.5 headroom. RAM still sizes the buffers, and the honest
# feasibility check below warns when the combination cannot fit.

ST_EXPECTED_USERS=0

# capacity_apply_users — override ST_CONNTRACK from expected users (config
# key expected_users; the --users CLI flag wins when given). No-op when 0.
capacity_apply_users() {
  local users ct
  users="$(config_get expected_users 0)"
  if [[ ${ST_AUTO_USERS:-} =~ ^[0-9]+$ ]] && ((${ST_AUTO_USERS:-0} > 0)); then
    users="$ST_AUTO_USERS"
  fi
  [[ $users =~ ^[0-9]+$ ]] || users=0
  ST_EXPECTED_USERS="$users"
  ((users > 0)) || return 0

  ct=$((users * 24 * 3 / 2))
  ((ct < 65536)) && ct=65536
  ((ct > 4194304)) && ct=4194304
  ST_CONNTRACK="$ct"
  return 0
}

# capacity_warning — prints an honest RAM-math warning when the estimated
# need (conntrack + ~0.5 MB proxy userspace per online user) crowds >75% of
# RAM; prints nothing when the sizing fits.
capacity_warning() {
  ((ST_EXPECTED_USERS > 0)) || return 0
  local ram_mb ct_mb proxy_mb need_mb
  ram_mb="$(mem_total_mb)"
  ct_mb=$((ST_CONNTRACK * 300 / 1048576))
  proxy_mb=$((ST_EXPECTED_USERS / 2))
  need_mb=$((ct_mb + proxy_mb))
  if ((ram_mb > 0 && need_mb > ram_mb * 3 / 4)); then
    printf 'estimated need ~%d MB (conntrack %d + proxy ~%d) vs %d MB RAM — OOM risk at peak. Split users across nodes or add RAM (rule of thumb: ~8 GB per 10k users).' \
      "$need_mb" "$ct_mb" "$proxy_mb" "$ram_mb"
  fi
  return 0
}

# ------------------------- src/modules/sysctl.sh -------------------------
# ============================================================================
# modules/sysctl.sh — kernel network tuning. Implements docs/SYSCTL.md
# exactly: Layer 1 (base) always, Layer 2 forwarding keys for VPN profiles.
# Every written file is tracked via st_track_file for rollback.
# ============================================================================

readonly ST_SYSCTL_FILE='/etc/sysctl.d/99-server-tools.conf'
readonly ST_MODULES_FILE='/etc/modules-load.d/server-tools.conf'
readonly ST_MODPROBE_FILE='/etc/modprobe.d/server-tools.conf'

ST_CC='cubic'
ST_QDISC='fq_codel'

sysctl_detect_bbr() {
  ST_CC='cubic'
  ST_QDISC='fq_codel'
  ver_ge "$(kernel_base)" "4.9" || return 0
  # Kernels with built-in BBR have no module to load; availability is
  # verified against the actual sysctl list right after.
  modprobe tcp_bbr 2>/dev/null || true
  if [[ " $(sysctl_get net.ipv4.tcp_available_congestion_control) " == *bbr* ]]; then
    ST_CC='bbr'
    ST_QDISC='fq'
  fi
  return 0
}

# _sysctl_reserved_ports — listening ports that sit inside our ephemeral
# range (10240-65535), comma-joined for ip_local_reserved_ports. Capped via
# awk (head would SIGPIPE the producer under pipefail).
_sysctl_reserved_ports() {
  has_cmd ss || return 0
  ss -tuln 2>/dev/null |
    awk 'NR > 1 {sub(/.*:/, "", $5); if ($5 ~ /^[0-9]+$/ && $5 >= 10240 && $5 <= 65535) print $5}' |
    sort -un | awk 'NR <= 32' | paste -sd, -
}

_sysctl_render() {
  local buf_bytes=$((ST_BUF_MB * 1048576))
  local ram_mb ram_pages
  ram_mb="$(mem_total_mb)"
  ram_pages=$((ram_mb * 256)) # 4 KiB pages

  cat <<EOF
# Generated by ${ST_NAME} v${ST_VERSION} (profile=${ST_PROFILE}, tier=${ST_TIER})
# The rationale for every key lives in docs/SYSCTL.md:
# ${ST_REPO_URL}

# --- Congestion control & queueing
net.core.default_qdisc = ${ST_QDISC}
net.ipv4.tcp_congestion_control = ${ST_CC}

# --- Connection accept path (tier ${ST_TIER})
net.core.somaxconn = ${ST_SOMAXCONN}
net.ipv4.tcp_max_syn_backlog = ${ST_SOMAXCONN}
net.core.netdev_max_backlog = ${ST_NETDEV_BACKLOG}
net.ipv4.tcp_syncookies = 1

# --- Ports, timers, keepalive
net.ipv4.ip_local_port_range = 10240 65535
net.ipv4.tcp_fin_timeout = 30
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_keepalive_time = 300
net.ipv4.tcp_keepalive_intvl = 60
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_notsent_lowat = 16384
# Protect TIME-WAIT sockets from RST assassination (RFC 1337).
net.ipv4.tcp_rfc1337 = 1
# Mode 1 probes only after a blackhole is detected (mode 2 is the harmful one).
net.ipv4.tcp_mtu_probing = 1

# --- Buffers (tier ${ST_TIER})
net.core.rmem_max = ${buf_bytes}
net.core.wmem_max = ${buf_bytes}
net.core.rmem_default = 262144
net.core.wmem_default = 262144
net.ipv4.tcp_rmem = 4096 87380 ${buf_bytes}
net.ipv4.tcp_wmem = 4096 65536 ${buf_bytes}
net.ipv4.udp_rmem_min = 16384
net.ipv4.udp_wmem_min = 16384
net.ipv4.udp_mem = $((ram_pages / 32)) $((ram_pages / 16)) $((ram_pages / 8))
net.core.optmem_max = 65536

# --- System capacity
fs.file-max = 2097152
vm.swappiness = 10
EOF

  # User-based capacity mode: bound total TCP memory explicitly so buffer
  # autotuning can never crowd a small-RAM host out of userspace memory.
  if ((ST_EXPECTED_USERS > 0)); then
    cat <<EOF

# --- TCP memory bounds (user-based capacity mode: ${ST_EXPECTED_USERS} users)
net.ipv4.tcp_mem = $((ram_pages * 10 / 100)) $((ram_pages * 13 / 100)) $((ram_pages * 16 / 100))
EOF
  fi

  # High-churn caps only where the connection volume justifies them.
  if [[ $ST_TIER == L || $ST_TIER == XL ]]; then
    local tw_buckets=524288 max_orphans=131072
    if [[ $ST_TIER == XL ]]; then
      tw_buckets=1048576
      max_orphans=262144
    fi
    cat <<EOF

# --- High-churn caps (tier ${ST_TIER})
net.ipv4.tcp_max_tw_buckets = ${tw_buckets}
net.ipv4.tcp_max_orphans = ${max_orphans}
EOF
  fi

  # Keep detected service ports out of the ephemeral source-port pool so an
  # outgoing connection can never collide with a panel/node listener.
  local reserved
  reserved="$(_sysctl_reserved_ports)" || reserved=''
  if [[ -n $reserved ]]; then
    cat <<EOF

# --- Listening ports inside the ephemeral range, reserved automatically
net.ipv4.ip_local_reserved_ports = ${reserved}
EOF
  fi

  if profile_wants_forwarding; then
    cat <<EOF

# --- VPN workload (profile ${ST_PROFILE}): routing + conntrack + hardening
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
net.netfilter.nf_conntrack_max = ${ST_CONNTRACK}
# Kernel default is 5 DAYS — idle VPN flows would exhaust the table.
net.netfilter.nf_conntrack_tcp_timeout_established = 3600
net.ipv4.conf.all.rp_filter = 2
net.ipv4.conf.default.rp_filter = 2
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.default.send_redirects = 0
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.default.accept_source_route = 0
EOF
  fi
}

# sysctl_dry_run — render the exact config this run would write and diff
# every key against the live kernel. Applies NOTHING and tracks nothing.
sysctl_dry_run() {
  sysctl_detect_bbr
  local rendered line key value current changed=0 total=0
  rendered="$(_sysctl_render)"

  printf '%s[Rendered %s]%s\n%s\n\n' "$C_TITLE" "$ST_SYSCTL_FILE" "$C_RESET" "$rendered"
  printf '%s[Diff vs live kernel]%s\n' "$C_TITLE" "$C_RESET"
  while IFS= read -r line; do
    [[ -z $line || $line == \#* ]] && continue
    key="${line%%=*}"
    key="${key//[[:space:]]/}"
    value="${line#*=}"
    value="${value#"${value%%[![:space:]]*}"}"
    current="$(sysctl_get "$key")"
    total=$((total + 1))
    # Normalize runs of whitespace so multi-value keys compare fairly.
    if [[ "$(tr -s ' \t' ' ' <<<"$current")" != "$(tr -s ' \t' ' ' <<<"$value")" ]]; then
      printf '  %s%-50s%s %s -> %s\n' "$C_KEY" "$key" "$C_RESET" "${current}" "${value}"
      changed=$((changed + 1))
    fi
  done <<<"$rendered"

  ((changed == 0)) && printf '  (kernel already matches this profile)\n'
  printf '\n%s%d of %d keys would change. Nothing was applied.%s\n' \
    "$C_WARN" "$changed" "$total" "$C_RESET"
}

sysctl_apply() {
  if ! has_cmd sysctl; then
    log_error "sysctl command not found — cannot tune the kernel."
    return 1
  fi

  sysctl_detect_bbr

  local modules=()
  [[ $ST_CC == bbr ]] && modules+=(tcp_bbr)

  if profile_wants_forwarding; then
    # Without the module loaded, net.netfilter.* keys silently fail to apply.
    modprobe nf_conntrack 2>/dev/null ||
      log_warn "nf_conntrack module unavailable — conntrack keys may not apply."
    modules+=(nf_conntrack)
  fi

  st_track_file "$ST_SYSCTL_FILE"
  mkdir -p "$(dirname "$ST_SYSCTL_FILE")"
  _sysctl_render >"$ST_SYSCTL_FILE"

  if ((${#modules[@]} > 0)); then
    st_track_file "$ST_MODULES_FILE"
    mkdir -p "$(dirname "$ST_MODULES_FILE")"
    {
      printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
      printf '%s\n' "${modules[@]}"
    } >"$ST_MODULES_FILE"
  fi

  if profile_wants_forwarding; then
    # The conntrack hash table must scale with the table itself; the runtime
    # knob is a module parameter, persisted for reboots via modprobe.d.
    local hashsize=$((ST_CONNTRACK / 4))
    st_track_file "$ST_MODPROBE_FILE"
    mkdir -p "$(dirname "$ST_MODPROBE_FILE")"
    printf '# Generated by %s v%s\noptions nf_conntrack hashsize=%s\n' \
      "$ST_NAME" "$ST_VERSION" "$hashsize" >"$ST_MODPROBE_FILE"
    if [[ -w /sys/module/nf_conntrack/parameters/hashsize ]]; then
      printf '%s' "$hashsize" >/sys/module/nf_conntrack/parameters/hashsize 2>>"$ST_LOG_FILE" ||
        log_warn "Could not resize the conntrack hash table live (persisted for next boot)."
    fi
  fi

  # Apply; per-key errors land in the log instead of vanishing — the keys we
  # care about are verified individually right after.
  sysctl --system >/dev/null 2>>"$ST_LOG_FILE" || true

  # default_qdisc only affects NEW interfaces; switch the live default
  # interface too so the change is complete without a reboot.
  local iface
  iface="$(net_default_iface)" || iface=''
  if [[ -n $iface ]] && has_cmd tc; then
    tc qdisc replace dev "$iface" root "$ST_QDISC" 2>>"$ST_LOG_FILE" ||
      log_warn "Could not switch ${iface} to ${ST_QDISC} live (it applies after reboot)."
  fi

  local cc_now qdisc_now rc=0
  cc_now="$(sysctl_get net.ipv4.tcp_congestion_control)"
  qdisc_now="$(sysctl_get net.core.default_qdisc)"
  if [[ $cc_now != "$ST_CC" || $qdisc_now != "$ST_QDISC" ]]; then
    log_warn "sysctl verify: cc=${cc_now}, qdisc=${qdisc_now} (expected ${ST_CC}/${ST_QDISC})"
    rc=3
  fi
  if profile_wants_forwarding; then
    local ct_now
    ct_now="$(sysctl_get net.netfilter.nf_conntrack_max)"
    if [[ $ct_now != "$ST_CONNTRACK" ]]; then
      log_warn "sysctl verify: nf_conntrack_max=${ct_now} (expected ${ST_CONNTRACK})"
      rc=3
    fi
  fi

  log_info "sysctl applied: cc=${cc_now}, qdisc=${qdisc_now}, tier=${ST_TIER}, profile=${ST_PROFILE}"
  return "$rc"
}

# ------------------------- src/modules/dns.sh -------------------------
# ============================================================================
# modules/dns.sh — DNS provider selection and safe application.
#
# Selection and application are deliberately decoupled: "Keep current DNS"
# really keeps it (the legacy v1 bug silently applied the default provider).
# No Domains=~. hijack; systemd-resolved gets a drop-in, plain systems get
# a tracked /etc/resolv.conf rewrite.
# ============================================================================

ST_DNS1=''
ST_DNS2=''

# Format: name|primary|secondary
# Iran-hosted anti-sanction resolvers with PUBLIC IPs only — services like
# 403.online announce private-range addresses that only route inside Iran.
readonly -a ST_DNS_PROVIDERS=(
  'Cloudflare|1.1.1.1|1.0.0.1'
  'Google|8.8.8.8|8.8.4.4'
  'Quad9|9.9.9.9|149.112.112.112'
  'OpenDNS|208.67.222.222|208.67.220.220'
  'Shecan (for Iran-hosted servers)|178.22.122.100|185.51.200.2'
  'Electro (for Iran-hosted servers)|78.157.42.100|78.157.42.101'
  'Begzar (for Iran-hosted servers)|185.55.226.26|185.55.225.25'
)

# is_valid_ip — IPv4 strictly, IPv6 loosely (contains a colon, no spaces).
is_valid_ip() {
  is_valid_ipv4 "$1" || [[ $1 == *:* && $1 != *' '* && -n $1 ]]
}

# _dns_probe_ms IP — a real DNS query time when dig exists (resolvers often
# deprioritize ICMP, so ping understates real performance); ping fallback.
_dns_probe_ms() {
  if has_cmd dig; then
    dig +tries=1 +time=2 "@$1" google.com A 2>/dev/null |
      awk '/Query time:/ {print $4; exit}'
  elif has_cmd ping; then
    ping -c 1 -W 1 "$1" 2>/dev/null |
      awk -F'time=' '/time=/ {split($2, a, " "); print a[1]; exit}'
  fi
}

dns_latency_test() {
  if ! has_cmd dig && ! has_cmd ping; then
    printf 'Neither dig nor ping is available on this system.\n'
    return 0
  fi
  local entry name ip1 ip2 ms method='ping'
  has_cmd dig && method='real DNS query (dig)'
  printf '%sLatency per provider — measured via %s:%s\n' "$C_MUTED" "$method" "$C_RESET"
  for entry in "${ST_DNS_PROVIDERS[@]}"; do
    IFS='|' read -r name ip1 ip2 <<<"$entry"
    ms="$(_dns_probe_ms "$ip1")" || ms=''
    if [[ -n $ms ]]; then
      printf '  %-34s %s ms\n' "$name" "$ms"
    else
      printf '  %-34s timeout\n' "$name"
    fi
  done
}

# dns_select_menu — sets ST_DNS1/ST_DNS2 and returns 0 when the user picked
# a provider to apply; returns 1 for "keep current" (caller MUST skip apply).
dns_select_menu() {
  local choice entry name ip1 ip2 i
  while true; do
    printf '\n%s[DNS provider]%s\n' "$C_TITLE" "$C_RESET"
    i=1
    for entry in "${ST_DNS_PROVIDERS[@]}"; do
      IFS='|' read -r name ip1 ip2 <<<"$entry"
      ui_menu_item "$i" "$name" "${ip1} / ${ip2}"
      i=$((i + 1))
    done
    ui_menu_item 8 "Custom" "enter your own (IPv4 or IPv6)"
    ui_menu_item t "Latency test" "measure every provider first"
    ui_menu_item 0 "Keep current DNS" "no DNS change"
    read -rp "Select [0]: " choice || return 1
    case "${choice:-0}" in
      [1-7])
        IFS='|' read -r name ST_DNS1 ST_DNS2 <<<"${ST_DNS_PROVIDERS[$((choice - 1))]}"
        return 0
        ;;
      8)
        read -rp "Primary DNS: " ST_DNS1 || return 1
        read -rp "Secondary DNS: " ST_DNS2 || return 1
        if is_valid_ip "$ST_DNS1" && is_valid_ip "$ST_DNS2"; then
          return 0
        fi
        printf '%sInvalid address — DNS left unchanged.%s\n' "$C_ERR" "$C_RESET"
        return 1
        ;;
      t | T) dns_latency_test ;;
      0) return 1 ;;
      *) printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET" ;;
    esac
  done
}

# dns_resolve_cli VALUE — non-interactive parsing for --dns: a provider name
# (cloudflare|google|quad9|opendns|shecan) or "primary,secondary" addresses.
dns_resolve_cli() {
  local value="$1"
  case "${value,,}" in
    cloudflare)
      ST_DNS1='1.1.1.1'
      ST_DNS2='1.0.0.1'
      ;;
    google)
      ST_DNS1='8.8.8.8'
      ST_DNS2='8.8.4.4'
      ;;
    quad9)
      ST_DNS1='9.9.9.9'
      ST_DNS2='149.112.112.112'
      ;;
    opendns)
      ST_DNS1='208.67.222.222'
      ST_DNS2='208.67.220.220'
      ;;
    shecan)
      ST_DNS1='178.22.122.100'
      ST_DNS2='185.51.200.2'
      ;;
    *,*)
      ST_DNS1="${value%%,*}"
      ST_DNS2="${value#*,}"
      is_valid_ip "$ST_DNS1" && is_valid_ip "$ST_DNS2"
      ;;
    *) return 1 ;;
  esac
}

dns_apply() {
  [[ -n $ST_DNS1 && -n $ST_DNS2 ]] || return 2 # nothing selected — skip

  if has_cmd systemctl && systemctl is-active --quiet systemd-resolved 2>/dev/null; then
    local dropin='/etc/systemd/resolved.conf.d/99-server-tools.conf'
    st_track_file "$dropin"
    mkdir -p "$(dirname "$dropin")"
    cat >"$dropin" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Resolve]
DNS=${ST_DNS1} ${ST_DNS2}
FallbackDNS=${ST_DNS2}
# Encrypt DNS when the resolver supports it, fall back to plain otherwise.
DNSOverTLS=opportunistic
EOF
    if ! systemctl restart systemd-resolved 2>>"$ST_LOG_FILE"; then
      log_warn "systemd-resolved restart failed — drop-in written but not active yet."
      return 3
    fi
    # Apps read /etc/resolv.conf directly; if it does not point at the
    # resolved stub, the drop-in silently changes nothing for them.
    if ! grep -q '127.0.0.53' /etc/resolv.conf 2>/dev/null; then
      log_warn "resolv.conf does not use the systemd-resolved stub (127.0.0.53) — some apps may bypass the new DNS."
      return 3
    fi
  else
    st_track_file /etc/resolv.conf
    if has_cmd chattr; then
      # Some providers lock resolv.conf with +i; unlock before writing.
      chattr -i /etc/resolv.conf 2>/dev/null || true
    fi
    rm -f /etc/resolv.conf
    cat >/etc/resolv.conf <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
nameserver ${ST_DNS1}
nameserver ${ST_DNS2}
# Fast failover: 2s per try, alternate between the two servers.
options timeout:2 attempts:2 rotate
EOF
    log_info "resolv.conf written directly (no systemd-resolved); note that a DHCP client may overwrite it."
  fi

  config_set dns_primary "$ST_DNS1"
  config_set dns_secondary "$ST_DNS2"
  log_info "DNS applied: ${ST_DNS1} / ${ST_DNS2}"
  return 0
}

# ------------------------- src/modules/swap.sh -------------------------
# ============================================================================
# modules/swap.sh — swap provisioning when no swap exists at all.
#
# Backends (config key swap_backend = auto | file | zram):
#   file — swap file on disk: real extra capacity, the universal safe default.
#   zram — compressed in-RAM swap: no disk needed, much faster than slow VPS
#          disks, but adds no capacity beyond RAM itself.
#   auto — file first (best scenario for most servers); falls back to zram
#          automatically when the disk is too small for a swap file.
#
# The fstab entry / boot unit is only written AFTER swapon verifiably works.
# ============================================================================

readonly ST_ZRAM_UNIT='/etc/systemd/system/server-tools-zram.service'

swap_is_active() {
  [[ -r /proc/swaps ]] && awk 'NR > 1 {found = 1} END {exit !found}' /proc/swaps
}

# _swap_file_setup SIZE_MB
_swap_file_setup() {
  local size_mb="$1" swapfile='/swapfile' fstype
  st_track_file /etc/fstab
  st_track_file "$swapfile" # recorded as "created" so rollback removes it

  fstype="$(stat -f -c %T / 2>/dev/null)" || fstype=''
  if [[ $fstype == btrfs ]]; then
    # CoW must be disabled on the empty file before any data is written, and
    # fallocate'd files are not usable as swap on btrfs — always use dd.
    touch "$swapfile"
    if has_cmd chattr; then
      chattr +C "$swapfile" 2>/dev/null || true # best effort; swapon verifies below
    fi
    dd if=/dev/zero of="$swapfile" bs=1M count="$size_mb" status=none 2>>"$ST_LOG_FILE" || return 1
  else
    if ! fallocate -l "${size_mb}M" "$swapfile" 2>/dev/null; then
      dd if=/dev/zero of="$swapfile" bs=1M count="$size_mb" status=none 2>>"$ST_LOG_FILE" || return 1
    fi
  fi

  chmod 600 "$swapfile"
  mkswap "$swapfile" >/dev/null 2>>"$ST_LOG_FILE" || return 1
  if ! swapon "$swapfile" 2>>"$ST_LOG_FILE"; then
    log_error "swapon failed (filesystem: ${fstype:-unknown}) — swap file removed, fstab untouched."
    rm -f "$swapfile"
    return 1
  fi

  if ! grep -qE '^[[:space:]]*/swapfile[[:space:]]' /etc/fstab 2>/dev/null; then
    printf '/swapfile none swap sw 0 0\n' >>/etc/fstab
  fi
  log_info "Swap file enabled: ${size_mb} MB (fs: ${fstype:-unknown})."
  return 0
}

# _swap_zram_setup SIZE_MB — compressed swap in RAM, priority above any
# future disk swap. Boot persistence via a oneshot unit (nothing resident).
_swap_zram_setup() {
  local size_mb="$1"
  ((size_mb < 256)) && size_mb=256
  ((size_mb > 4096)) && size_mb=4096

  if ! modprobe zram 2>>"$ST_LOG_FILE" || [[ ! -b /dev/zram0 ]]; then
    log_error "zram kernel module unavailable on this system."
    return 1
  fi
  # lz4 beats the default algorithm on weak vCPUs; not fatal when missing.
  echo lz4 >/sys/block/zram0/comp_algorithm 2>/dev/null || true
  if ! echo "${size_mb}M" >/sys/block/zram0/disksize 2>>"$ST_LOG_FILE"; then
    log_error "Could not size /dev/zram0."
    return 1
  fi
  mkswap /dev/zram0 >/dev/null 2>>"$ST_LOG_FILE" || return 1
  if ! swapon -p 100 /dev/zram0 2>>"$ST_LOG_FILE"; then
    log_error "swapon on /dev/zram0 failed."
    return 1
  fi

  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    st_track_file "$ST_ZRAM_UNIT"
    cat >"$ST_ZRAM_UNIT" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Unit]
Description=ServerTools zram swap (oneshot, exits after boot)

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'modprobe zram && { echo lz4 > /sys/block/zram0/comp_algorithm 2>/dev/null; true; } && echo ${size_mb}M > /sys/block/zram0/disksize && mkswap /dev/zram0 && swapon -p 100 /dev/zram0'
ExecStop=/bin/bash -c 'swapoff /dev/zram0 && echo 1 > /sys/block/zram0/reset'

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
    if systemctl enable server-tools-zram.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-zram.service
    else
      log_warn "Could not enable zram boot persistence — active now, gone after reboot."
    fi
  else
    log_warn "No systemd — zram swap is active now but will not survive a reboot."
  fi

  log_info "zram swap enabled: ${size_mb} MB compressed (priority 100)."
  return 0
}

swap_apply() {
  if swap_is_active; then
    log_info "Swap already active — skipped."
    return 2
  fi

  local backend size_mb ram_mb avail_mb disk_ok=0
  backend="$(config_get swap_backend auto)"
  size_mb="$(config_get swap_size_mb 2048)"
  [[ $size_mb =~ ^[0-9]+$ ]] || size_mb=2048
  ram_mb="$(mem_total_mb)"

  # Disk headroom check: swap size + 1 GB safety margin.
  avail_mb="$(df -Pm / 2>/dev/null | awk 'NR == 2 {print $4}')" || avail_mb=0
  [[ $avail_mb =~ ^[0-9]+$ ]] || avail_mb=0
  ((avail_mb >= size_mb + 1024)) && disk_ok=1

  case "$backend" in
    file)
      if ((disk_ok == 0)); then
        log_error "Not enough free disk for a ${size_mb} MB swap file (available: ${avail_mb} MB)."
        return 1
      fi
      _swap_file_setup "$size_mb"
      ;;
    zram)
      _swap_zram_setup "$((ram_mb / 2))"
      ;;
    *) # auto — real disk capacity first, compressed RAM as the fallback.
      if ((disk_ok)); then
        _swap_file_setup "$size_mb"
      else
        log_warn "Disk too small for a swap file — using zram (compressed RAM) instead."
        _swap_zram_setup "$((ram_mb / 2))"
      fi
      ;;
  esac
}

# ------------------------- src/modules/limits.sh -------------------------
# ============================================================================
# modules/limits.sh — file-descriptor limits for 100k+ concurrent sockets.
# Uses a systemd drop-in instead of sed-editing system.conf, so rollback is
# a clean file removal (legacy v1 mutated /etc/systemd/system.conf in place).
# ============================================================================

readonly ST_LIMITS_FILE='/etc/security/limits.d/99-server-tools.conf'
readonly ST_SYSTEMD_DROPIN='/etc/systemd/system.conf.d/99-server-tools.conf'

# Set when limits were (re)written this run — running services keep their
# old nofile until restarted, so the optimizer offers a restart afterwards.
ST_LIMITS_CHANGED=0

limits_apply() {
  ST_LIMITS_CHANGED=1
  st_track_file "$ST_LIMITS_FILE"
  mkdir -p "$(dirname "$ST_LIMITS_FILE")"
  cat >"$ST_LIMITS_FILE" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
* soft nofile 1048576
* hard nofile 1048576
root soft nofile 1048576
root hard nofile 1048576
EOF

  if [[ -d /etc/systemd ]]; then
    st_track_file "$ST_SYSTEMD_DROPIN"
    mkdir -p "$(dirname "$ST_SYSTEMD_DROPIN")"
    cat >"$ST_SYSTEMD_DROPIN" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Manager]
DefaultLimitNOFILE=1048576
EOF
    if has_cmd systemctl && ! systemctl daemon-reexec 2>>"$ST_LOG_FILE"; then
      log_warn "systemd daemon-reexec failed — new limits take effect after reboot."
      return 3
    fi
  fi

  log_info "nofile limits set to 1048576 (PAM + systemd drop-in)."
  return 0
}

# ------------------------- src/modules/extras.sh -------------------------
# ============================================================================
# modules/extras.sh — base-layer hygiene: journald disk cap and NTP sync.
# Small-disk VPSes fill up with journal logs; Reality/TLS handshakes need
# an accurate clock.
# ============================================================================

readonly ST_JOURNALD_DROPIN='/etc/systemd/journald.conf.d/99-server-tools.conf'

extras_apply() {
  local rc=0 did_anything=0

  if [[ -d /etc/systemd ]]; then
    st_track_file "$ST_JOURNALD_DROPIN"
    mkdir -p "$(dirname "$ST_JOURNALD_DROPIN")"
    cat >"$ST_JOURNALD_DROPIN" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Journal]
SystemMaxUse=100M
RuntimeMaxUse=50M
EOF
    if has_cmd systemctl; then
      systemctl restart systemd-journald 2>>"$ST_LOG_FILE" ||
        log_warn "journald restart failed — the disk cap applies after next boot."
    fi
    did_anything=1
  fi

  if has_cmd timedatectl; then
    if ! timedatectl set-ntp true 2>>"$ST_LOG_FILE"; then
      log_warn "Could not enable NTP via timedatectl."
      rc=3
    fi
    did_anything=1
  fi

  ((did_anything)) || return 2
  return "$rc"
}

# ------------------------- src/modules/security.sh -------------------------
# ============================================================================
# modules/security.sh — Layer 3 optional hardening: UFW, fail2ban, SSH.
#
# Everything here is consent-based (CLAUDE.md rule 1). fail2ban is the only
# resident service in the whole project and its cost is stated before the
# user agrees. The SSH allow rule always lands before any deny rule, and the
# sshd drop-in is validated with `sshd -t` before restart — no lockouts.
# ============================================================================

readonly ST_F2B_JAIL='/etc/fail2ban/jail.d/99-server-tools.local'
readonly ST_SSHD_DROPIN='/etc/ssh/sshd_config.d/99-server-tools.conf'

detect_ssh_port() {
  local port=''
  port="$(awk '/^[[:space:]]*[Pp]ort[[:space:]]/ {print $2; exit}' /etc/ssh/sshd_config 2>/dev/null)" || port=''
  if [[ -z $port ]] && has_cmd ss; then
    port="$(ss -tnlp 2>/dev/null | awk '/sshd/ {sub(/.*:/, "", $4); print $4; exit}')" || port=''
  fi
  [[ $port =~ ^[0-9]+$ ]] || port=22
  printf '%s' "$port"
}

security_ufw() {
  ui_section "UFW firewall"
  if ! has_cmd ufw; then
    ui_confirm "UFW is not installed. Install it now?" || return 0
    if ! pkg_install ufw; then
      log_error "UFW installation failed — see the log."
      return 0
    fi
  fi

  local ssh_port
  ssh_port="$(detect_ssh_port)"
  printf 'Detected SSH port: %s — it is allowed FIRST, so you cannot be locked out.\n' "$ssh_port"
  if ! ufw allow "${ssh_port}/tcp" >/dev/null 2>>"$ST_LOG_FILE"; then
    log_error "Could not add the SSH allow rule — aborting before any deny rule."
    return 0
  fi
  ufw default deny incoming >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Could not set default deny incoming."
  ufw default allow outgoing >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Could not set default allow outgoing."

  local ports p
  read -rp "Extra ports to allow (e.g. 443/tcp 80/tcp 51820/udp) [Enter=none]: " ports || ports=''
  if [[ -n $ports ]]; then
    local IFS=' ' # the global IFS has no space — restore word splitting here
    for p in $ports; do
      if [[ $p =~ ^[0-9]+(/(tcp|udp))?$ ]]; then
        ufw allow "$p" >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Rule failed: ${p}"
      else
        log_warn "Skipped invalid port spec: ${p}"
      fi
    done
  fi

  if has_cmd docker && docker ps -q 2>/dev/null | grep -q .; then
    printf '%sWarning:%s Docker publishes container ports directly in iptables and\n' "$C_WARN" "$C_RESET"
    printf 'BYPASSES UFW — published panel/node ports stay reachable regardless of\n'
    printf 'these rules (see Network tools > Docker+UFW audit).\n'
  fi

  if ui_confirm "Enable UFW now?"; then
    if ufw --force enable >/dev/null 2>>"$ST_LOG_FILE"; then
      printf '%sUFW enabled.%s\n' "$C_OK" "$C_RESET"
      ufw status verbose 2>/dev/null || log_warn "Could not print UFW status."
    else
      log_error "Enabling UFW failed — see the log."
      return 0
    fi
  fi
  printf '%sNote:%s firewall state is not covered by manifest rollback — revert with: ufw disable\n' \
    "$C_MUTED" "$C_RESET"
  log_info "UFW configured (SSH ${ssh_port}/tcp allowed)."
}

security_fail2ban() {
  ui_section "fail2ban (SSH brute-force protection)"
  printf 'fail2ban runs as a small resident service (~20 MB RAM) — the only\n'
  printf 'exception to the zero-footprint rule, and only with your consent.\n'
  ui_confirm "Install and enable fail2ban?" || return 0

  if ! has_cmd fail2ban-server && ! pkg_install fail2ban; then
    log_error "fail2ban installation failed — see the log."
    return 0
  fi

  local ssh_port
  ssh_port="$(detect_ssh_port)"
  st_track_file "$ST_F2B_JAIL"
  mkdir -p "$(dirname "$ST_F2B_JAIL")"
  cat >"$ST_F2B_JAIL" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[sshd]
enabled = true
port = ${ssh_port}
backend = systemd
maxretry = 5
findtime = 10m
bantime = 1h
EOF

  if has_cmd systemctl &&
    systemctl enable fail2ban >/dev/null 2>>"$ST_LOG_FILE" &&
    systemctl restart fail2ban 2>>"$ST_LOG_FILE"; then
    printf '%sfail2ban active%s (sshd jail on port %s, ban 1h after 5 tries).\n' \
      "$C_OK" "$C_RESET" "$ssh_port"
    log_info "fail2ban enabled (sshd jail, port ${ssh_port})."
  else
    log_error "fail2ban could not be enabled — see the log."
  fi
}

security_ssh() {
  ui_section "SSH hardening"
  if [[ ! -d /etc/ssh/sshd_config.d ]]; then
    log_warn "This system has no /etc/ssh/sshd_config.d — skipping (editing sshd_config in place is not safe enough)."
    return 0
  fi

  local lines=('UseDNS no')
  if [[ -s /root/.ssh/authorized_keys ]]; then
    printf 'An SSH key for root exists.\n'
    printf '%sVerify key login works in a second terminal BEFORE confirming.%s\n' "$C_WARN" "$C_RESET"
    if ui_confirm "Disable password authentication?"; then
      lines+=('PasswordAuthentication no')
    fi
  else
    printf '%sNo /root/.ssh/authorized_keys found — password login stays enabled.%s\n' "$C_WARN" "$C_RESET"
  fi

  st_track_file "$ST_SSHD_DROPIN"
  {
    printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
    printf '%s\n' "${lines[@]}"
  } >"$ST_SSHD_DROPIN"

  if has_cmd sshd && ! sshd -t 2>>"$ST_LOG_FILE"; then
    rm -f "$ST_SSHD_DROPIN"
    log_error "sshd config validation failed — drop-in removed, nothing changed."
    return 0
  fi
  if has_cmd systemctl; then
    # Service name differs across distros (ssh on Debian/Ubuntu, sshd elsewhere).
    systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>>"$ST_LOG_FILE" ||
      log_warn "Could not restart sshd — settings apply on its next restart."
  fi
  printf '%sApplied:%s %s\n' "$C_OK" "$C_RESET" "${lines[*]}"
  log_info "SSH hardening drop-in applied: ${lines[*]}"
}

security_menu() {
  local choice
  while true; do
    ui_logo
    ui_title "Security (Layer 3 — optional, consent-based)"
    ui_menu_item 1 "UFW firewall" "SSH-safe setup, extra ports, Docker warning"
    ui_menu_item 2 "fail2ban" "SSH brute-force bans (resident service ~20 MB)"
    ui_menu_item 3 "SSH hardening" "UseDNS off, optional key-only login (validated)"
    ui_menu_item 0 "Back"
    ui_hr
    read -rp "Select: " choice || return 0
    case "${choice:-}" in
      1)
        security_ufw
        ui_pause
        ;;
      2)
        security_fail2ban
        ui_pause
        ;;
      3)
        security_ssh
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/modules/vpn.sh -------------------------
# ============================================================================
# modules/vpn.sh — VPN-aware non-sysctl fixes.
#
# MSS clamping is the most common fix for "WireGuard connects but pages
# don't load" behind NAT. Persistence uses a systemd ONESHOT unit: it runs
# once at boot and exits — no resident process, zero-footprint compliant.
# ============================================================================

readonly ST_MSS_UNIT='/etc/systemd/system/server-tools-mss.service'
# The comma in SYN,RST is iptables syntax, not an array-separator mistake.
# shellcheck disable=SC2054
readonly -a ST_MSS_RULE=(
  FORWARD -p tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu
)

vpn_mss_clamp() {
  ui_section "MSS clamping (TCP over tunnels/NAT)"
  printf 'Clamps TCP MSS to the path MTU on forwarded traffic. Fixes the classic\n'
  printf '"VPN connects but sites do not load" symptom (WireGuard, tunnels, NAT).\n'
  if ! has_cmd iptables; then
    log_error "iptables not available — cannot apply MSS clamping."
    return 0
  fi
  ui_confirm "Apply MSS clamping now?" || return 0

  if ! iptables -t mangle -C "${ST_MSS_RULE[@]}" 2>/dev/null; then
    if ! iptables -t mangle -A "${ST_MSS_RULE[@]}" 2>>"$ST_LOG_FILE"; then
      log_error "Could not add the IPv4 MSS rule — see the log."
      return 0
    fi
  fi
  if has_cmd ip6tables && ! ip6tables -t mangle -C "${ST_MSS_RULE[@]}" 2>/dev/null; then
    ip6tables -t mangle -A "${ST_MSS_RULE[@]}" 2>>"$ST_LOG_FILE" ||
      log_warn "IPv6 MSS rule failed (IPv6 clamping skipped)."
  fi

  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    local ipt ip6t
    ipt="$(command -v iptables)"
    ip6t="$(command -v ip6tables)" || ip6t=''
    st_track_file "$ST_MSS_UNIT"
    {
      printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
      printf '[Unit]\nDescription=ServerTools MSS clamping (oneshot, exits after boot)\nAfter=network-pre.target\nWants=network-pre.target\n\n'
      printf '[Service]\nType=oneshot\nRemainAfterExit=yes\n'
      printf 'ExecStart=%s -t mangle -A %s\n' "$ipt" "${ST_MSS_RULE[*]}"
      [[ -n $ip6t ]] && printf 'ExecStart=%s -t mangle -A %s\n' "$ip6t" "${ST_MSS_RULE[*]}"
      printf '\n[Install]\nWantedBy=multi-user.target\n'
    } >"$ST_MSS_UNIT"
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
    if systemctl enable server-tools-mss.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-mss.service
    else
      log_warn "Could not enable boot persistence for the MSS rule."
    fi
  else
    log_warn "No systemd — the MSS rule is active now but will not survive a reboot."
  fi

  printf '%sMSS clamping active%s (persisted via oneshot unit — nothing stays running).\n' \
    "$C_OK" "$C_RESET"
  log_info "MSS clamping applied."
}

vpn_docker_ufw_audit() {
  ui_section "Docker + UFW audit"
  local docker_on=0 ufw_on=0
  if has_cmd docker && docker ps -q 2>/dev/null | grep -q .; then
    docker_on=1
  fi
  if has_cmd ufw && ufw status 2>/dev/null | grep -q '^Status: active'; then
    ufw_on=1
  fi

  if ((docker_on == 0)); then
    printf 'No running Docker containers — no bypass risk.\n'
    return 0
  fi
  if ((ufw_on == 0)); then
    printf 'Docker is running but UFW is inactive — nothing to bypass (no firewall).\n'
    return 0
  fi

  printf '%sBoth Docker and UFW are active.%s Docker inserts its own iptables rules,\n' "$C_WARN" "$C_RESET"
  printf 'so ports published with -p/ports: are reachable EVEN IF UFW blocks them.\n'
  printf '\n%sPublished ports right now:%s\n' "$C_KEY" "$C_RESET"
  docker ps --format '  {{.Names}}: {{.Ports}}' 2>/dev/null ||
    log_warn "Could not list container ports."
  printf '\nMitigations: bind sensitive ports to 127.0.0.1 in compose, or use the\n'
  printf 'ufw-docker approach (planned in ROADMAP.md backlog).\n'
}

# ------------------------- src/modules/kernel.sh -------------------------
# ============================================================================
# modules/kernel.sh — ADVANCED, opt-in only: XanMod kernel for BBRv3.
#
# BBRv3 is not in mainline kernels; XanMod ships it. Replacing the kernel is
# the riskiest thing this project can do, so this flow is apt-only, warns
# twice, and never runs inside Quick/Auto optimize. After a reboot the
# existing sysctl config picks BBRv3 up automatically (it registers as
# "bbr"), so nothing else needs to change.
# ============================================================================

readonly ST_XANMOD_KEYRING='/usr/share/keyrings/xanmod-archive-keyring.gpg'
readonly ST_XANMOD_LIST='/etc/apt/sources.list.d/xanmod-release.list'

# _cpu_psabi_level — x86-64 microarchitecture level (1-4) for the right
# XanMod package variant.
_cpu_psabi_level() {
  local flags
  flags=" $(awk -F': ' '/^flags/ {print $2; exit}' /proc/cpuinfo 2>/dev/null) "
  if [[ $flags == *' avx512f '* && $flags == *' avx512bw '* ]]; then
    printf '4'
  elif [[ $flags == *' avx2 '* && $flags == *' bmi2 '* ]]; then
    printf '3'
  elif [[ $flags == *' sse4_2 '* && $flags == *' popcnt '* ]]; then
    printf '2'
  else
    printf '1'
  fi
}

kernel_xanmod_install() {
  ui_section "XanMod kernel / BBRv3 — ADVANCED"
  printf '%sThis REPLACES the distribution kernel.%s Risks: exotic VPS images or\n' "$C_WARN" "$C_RESET"
  printf 'custom drivers may fail to boot; a provider rescue console is your safety\n'
  printf 'net. Benefit: BBRv3 congestion control (not available in stock kernels).\n'
  ui_hr

  if ! has_cmd apt-get; then
    log_error "XanMod install is only supported on apt-based systems (Debian/Ubuntu)."
    return 0
  fi
  if ! has_cmd curl || ! has_cmd gpg; then
    log_error "curl and gpg are required for the XanMod repository setup."
    return 0
  fi
  if [[ "$(detect_virt)" == "openvz" || "$(detect_virt)" == "lxc" ]]; then
    log_error "Container virtualization ($(detect_virt)) cannot change its kernel."
    return 0
  fi

  ui_confirm "I understand this replaces the kernel and needs a reboot. Continue?" || return 0
  local level
  level="$(_cpu_psabi_level)"
  printf 'CPU supports microarchitecture level: x64v%s\n' "$level"
  ui_confirm "Install linux-xanmod-x64v${level} now? (several minutes)" || return 0

  st_track_file "$ST_XANMOD_KEYRING"
  if ! curl -fsSL --max-time 30 'https://dl.xanmod.org/archive.key' 2>>"$ST_LOG_FILE" |
    gpg --dearmor --yes -o "$ST_XANMOD_KEYRING" 2>>"$ST_LOG_FILE"; then
    log_error "Could not fetch the XanMod signing key — nothing changed."
    return 0
  fi

  st_track_file "$ST_XANMOD_LIST"
  printf 'deb [signed-by=%s] http://deb.xanmod.org releases main\n' \
    "$ST_XANMOD_KEYRING" >"$ST_XANMOD_LIST"

  export DEBIAN_FRONTEND=noninteractive
  printf 'Updating package index and installing (watch %s for details)...\n' "$ST_LOG_FILE"
  if ! apt-get update -qq >>"$ST_LOG_FILE" 2>&1 ||
    ! apt-get install -y "linux-xanmod-x64v${level}" >>"$ST_LOG_FILE" 2>&1; then
    log_error "XanMod installation failed — see the log. Repo files can be rolled back."
    return 0
  fi

  printf '%sXanMod kernel installed.%s Reboot to activate it; BBRv3 registers as\n' "$C_OK" "$C_RESET"
  printf '"bbr", so the existing sysctl config uses it automatically. Verify after\n'
  printf 'reboot with: uname -r  and  sysctl net.ipv4.tcp_congestion_control\n'
  log_info "XanMod linux-xanmod-x64v${level} installed (reboot pending)."
}

# ------------------------- src/modules/tools.sh -------------------------
# ============================================================================
# modules/tools.sh — on-demand network diagnostics. Read-only except where
# a tool explicitly says otherwise; nothing here runs in the background.
# ============================================================================

# Format: label|ip
readonly -a ST_PING_TARGETS=(
  'Iran - TCI (217.218.127.127)|217.218.127.127'
  'Iran - Shecan (178.22.122.100)|178.22.122.100'
  'Global - Cloudflare (1.1.1.1)|1.1.1.1'
  'Global - Google (8.8.8.8)|8.8.8.8'
)

tools_ping_matrix() {
  ui_section "Ping matrix (Iran + global, 3 probes each)"
  if ! has_cmd ping; then
    printf 'ping is not available on this system.\n'
    return 0
  fi
  printf 'Useful for judging how well this location serves users in Iran.\n\n'
  local entry label ip out loss avg
  for entry in "${ST_PING_TARGETS[@]}"; do
    IFS='|' read -r label ip <<<"$entry"
    out="$(ping -c 3 -W 1 "$ip" 2>/dev/null)" || out=''
    loss="$(grep -oE '[0-9]+(\.[0-9]+)?% packet loss' <<<"$out" | cut -d'%' -f1)" || loss=''
    avg="$(awk -F'/' '/rtt|round-trip/ {print $5; exit}' <<<"$out")" || avg=''
    if [[ -n $avg ]]; then
      printf '  %-38s loss %3s%%   avg %s ms\n' "$label" "${loss:-?}" "$avg"
    else
      printf '  %-38s %sunreachable%s\n' "$label" "$C_ERR" "$C_RESET"
    fi
  done
}

tools_tcp_status() {
  ui_section "TCP / conntrack live status"
  ui_kv "Congestion" "$(sysctl_get net.ipv4.tcp_congestion_control)"
  ui_kv "Qdisc" "$(sysctl_get net.core.default_qdisc)"
  ui_kv "Available cc" "$(sysctl_get net.ipv4.tcp_available_congestion_control)"
  ui_kv "IPv4 forward" "$(sysctl_get net.ipv4.ip_forward)"
  ui_kv "IPv6 forward" "$(sysctl_get net.ipv6.conf.all.forwarding)"

  local count max
  count="$(sysctl_get net.netfilter.nf_conntrack_count)"
  max="$(sysctl_get net.netfilter.nf_conntrack_max)"
  if [[ $count =~ ^[0-9]+$ && $max =~ ^[0-9]+$ && $max -gt 0 ]]; then
    ui_kv "Conntrack" "${count} / ${max} ($((count * 100 / max))% used)"
  else
    ui_kv "Conntrack" "module not loaded"
  fi
}

tools_listening_ports() {
  ui_section "Listening ports"
  if ! has_cmd ss; then
    printf 'ss (iproute2) is not available.\n'
    return 0
  fi
  # Display-only snapshot, capped with awk: `head` would SIGPIPE ss under
  # pipefail and turn a fine listing into a spurious warning.
  ss -tulnp 2>/dev/null | awk 'NR <= 30' || log_warn "Could not list sockets."
}

# tools_report — plain-text support bundle (also behind --report). Printed
# to stdout AND saved, so users can paste it into an issue/ticket directly.
tools_report() {
  local out="${ST_LIB_DIR}/report-${ST_RUN_ID}.txt"
  {
    printf '=== %s support report v%s — %s ===\n\n' "$ST_NAME" "$ST_VERSION" "$(date '+%F %T')"
    printf -- '--- System\n'
    printf 'OS: %s\nKernel: %s\nVirt: %s\nUptime: %s\n' \
      "$(os_pretty_name)" "$(kernel_release)" "$(detect_virt)" "$(uptime_pretty)"
    printf 'CPU: %s (%s cores)\nRAM: %s MB\nLoad: %s\n\n' \
      "$(cpu_model)" "$(cpu_cores)" "$(mem_total_mb)" "$(load_avg)"
    printf -- '--- Workload\n'
    printf 'Detected: %s\n' "$(detect_summary)"
    printf 'Saved profile/tier: %s / %s\n\n' \
      "$(config_get last_profile none)" "$(config_get last_tier -)"
    printf -- '--- Kernel tuning (live)\n'
    local key
    for key in net.ipv4.tcp_congestion_control net.core.default_qdisc \
      net.ipv4.tcp_mtu_probing net.ipv4.ip_forward net.ipv6.conf.all.forwarding \
      net.core.somaxconn net.core.rmem_max net.netfilter.nf_conntrack_max \
      net.netfilter.nf_conntrack_count fs.file-max vm.swappiness; do
      printf '%s = %s\n' "$key" "$(sysctl_get "$key")"
    done
    printf '\n'
    printf -- '--- Swap\n'
    if [[ -r /proc/swaps ]]; then cat /proc/swaps; else printf 'unavailable\n'; fi
    printf '\n'
    printf -- '--- Manifest (last 15 changes)\n'
    if [[ -f $ST_MANIFEST_FILE ]]; then
      awk 'NR > 1' "$ST_MANIFEST_FILE" | tail -n 15
    else
      printf 'no manifest yet\n'
    fi
    printf '\n'
    printf -- '--- Log (last 30 lines)\n'
    if [[ -f $ST_LOG_FILE ]]; then tail -n 30 "$ST_LOG_FILE"; else printf 'no log yet\n'; fi
    printf '\n=== end of report ===\n'
  } | tee "$out"
  printf '\n%sSaved:%s %s\n' "$C_OK" "$C_RESET" "$out"
  log_info "Support report written to ${out}."
}

tools_menu() {
  local choice
  while true; do
    ui_logo
    ui_title "Network & VPN Tools"
    ui_menu_item 1 "Ping matrix" "latency/loss to Iran + global targets"
    ui_menu_item 2 "DNS latency test" "ping every DNS provider"
    ui_menu_item 3 "TCP/conntrack status" "BBR, forwarding, table usage"
    ui_menu_item 4 "Listening ports" "ss -tulnp snapshot"
    ui_menu_item 5 "MSS clamping" "fix 'VPN connects but no sites' (WireGuard/NAT)"
    ui_menu_item 6 "Docker+UFW audit" "check the firewall bypass"
    ui_menu_item 7 "Support report" "full plain-text dump for issues/tickets"
    ui_menu_item 8 "XanMod kernel (BBRv3)" "ADVANCED — replaces the kernel"
    ui_menu_item 0 "Back"
    ui_hr
    read -rp "Select: " choice || return 0
    case "${choice:-}" in
      1)
        tools_ping_matrix
        ui_pause
        ;;
      2)
        dns_latency_test
        ui_pause
        ;;
      3)
        tools_tcp_status
        ui_pause
        ;;
      4)
        tools_listening_ports
        ui_pause
        ;;
      5)
        vpn_mss_clamp
        ui_pause
        ;;
      6)
        vpn_docker_ufw_audit
        ui_pause
        ;;
      7)
        tools_report
        ui_pause
        ;;
      8)
        kernel_xanmod_install
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/modules/selfupdate.sh -------------------------
# ============================================================================
# modules/selfupdate.sh — install as the `st` command and self-update.
#
# Downloads prefer the latest GitHub Release (with SHA-256 verification when
# sha256sum is available) and fall back to the raw main build only while no
# release exists yet. Every downloaded file must pass `bash -n` and a
# fingerprint check before it replaces anything.
# ============================================================================

readonly ST_INSTALL_PATH='/usr/local/bin/st'
readonly ST_URL_RELEASE='https://github.com/Sir-Adnan/server-tools/releases/latest/download/server-tools.sh'
readonly ST_URL_RELEASE_SUMS='https://github.com/Sir-Adnan/server-tools/releases/latest/download/SHA256SUMS'
readonly ST_URL_RAW='https://raw.githubusercontent.com/Sir-Adnan/server-tools/main/dist/server-tools.sh'

# _self_source_path — path of the running script, empty when running from a
# pipe/process substitution (`bash <(curl ...)` yields a non-reusable /dev/fd).
_self_source_path() {
  local src="${BASH_SOURCE[0]:-}"
  if [[ -f $src && -r $src ]]; then
    printf '%s' "$src"
    return 0
  fi
  return 1
}

# _self_download DEST — fetch, verify (checksum + parse + fingerprint), move.
_self_download() {
  local dest="$1" tmp="${ST_LIB_DIR}/download.$$" from_release=0
  if ! has_cmd curl; then
    log_error "curl is required to download ServerTools."
    return 1
  fi

  if curl -fsSL --max-time 60 "$ST_URL_RELEASE" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    from_release=1
  elif ! curl -fsSL --max-time 60 "$ST_URL_RAW" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    rm -f "$tmp"
    log_error "Download failed (release and raw fallback) — see the log."
    return 1
  fi

  if ((from_release)) && has_cmd sha256sum; then
    local sums expected actual
    sums="$(curl -fsSL --max-time 30 "$ST_URL_RELEASE_SUMS" 2>>"$ST_LOG_FILE")" || sums=''
    if [[ -n $sums ]]; then
      expected="$(awk '/server-tools\.sh/ {print $1; exit}' <<<"$sums")"
      actual="$(sha256sum "$tmp" | awk '{print $1}')"
      if [[ -n $expected && $expected != "$actual" ]]; then
        rm -f "$tmp"
        log_error "SHA-256 mismatch on the downloaded release — aborting."
        return 1
      fi
    fi
  fi

  if ! bash -n "$tmp" 2>>"$ST_LOG_FILE" || ! grep -q 'ST_NAME="ServerTools"' "$tmp"; then
    rm -f "$tmp"
    log_error "Downloaded file failed sanity checks — nothing was replaced."
    return 1
  fi
  mv -f "$tmp" "$dest"
}

st_self_install() {
  local src
  mkdir -p "$(dirname "$ST_INSTALL_PATH")"
  st_track_file "$ST_INSTALL_PATH"
  if src="$(_self_source_path)"; then
    cp -f "$src" "$ST_INSTALL_PATH"
  else
    printf 'Running from a pipe — downloading the current build instead.\n'
    _self_download "$ST_INSTALL_PATH" || return 1
  fi
  chmod 755 "$ST_INSTALL_PATH"
  printf '%sInstalled.%s Run %sst%s from now on; update anytime with: st --update\n' \
    "$C_OK" "$C_RESET" "$C_KEY" "$C_RESET"
  log_info "Installed to ${ST_INSTALL_PATH} (v${ST_VERSION})."
}

st_self_update() {
  local target new_ver staged="${ST_LIB_DIR}/update.$$"
  if [[ -f $ST_INSTALL_PATH ]]; then
    target="$ST_INSTALL_PATH"
  elif ! target="$(_self_source_path)"; then
    log_error "Not installed and not running from a file — use --install first."
    return 1
  fi

  # Single download: fetch once through the verifying path into a staging
  # file, read its version, and promote that exact verified file.
  _self_download "$staged" || return 1

  new_ver="$(grep -oE 'ST_VERSION="[^"]+"' "$staged" | head -n1 | cut -d'"' -f2)" || new_ver=''
  if [[ -z $new_ver ]]; then
    rm -f "$staged"
    log_error "Could not read the downloaded version — aborting."
    return 1
  fi
  if [[ $new_ver == "$ST_VERSION" ]]; then
    printf 'Already up to date (v%s).\n' "$ST_VERSION"
    rm -f "$staged"
    return 0
  fi

  st_track_file "$target"
  mv -f "$staged" "$target"
  chmod 755 "$target"
  printf '%sUpdated:%s v%s -> v%s (%s)\n' "$C_OK" "$C_RESET" "$ST_VERSION" "$new_ver" "$target"
  log_info "Self-updated: v${ST_VERSION} -> v${new_ver}."
}

# ------------------------- src/modules/optimize.sh -------------------------
# ============================================================================
# modules/optimize.sh — Quick/Custom Optimize flows:
# plan → confirm → apply steps with honest per-step outcomes → summary.
#
# NOTE: step functions run via `"$fn" || rc=$?`, which suppresses errexit for
# their whole body (bash semantics). Steps therefore signal outcomes with
# explicit return codes: 0=ok, 1=failed, 2=skipped, 3=applied with warnings.
# ============================================================================

ST_STEP_RESULTS=()
ST_STEP_IDX=0
ST_STEP_TOTAL=0

# --auto flags, filled by the CLI parser in 99-main.sh.
ST_AUTO_PROFILE=''
ST_AUTO_TIER=''
ST_AUTO_USERS=''
ST_AUTO_DNS=''
ST_AUTO_SWAP=1
ST_AUTO_LIMITS=1
ST_AUTO_EXTRAS=1

st_run_step() { # st_run_step TITLE FN
  local title="$1" fn="$2" rc=0
  ST_STEP_IDX=$((ST_STEP_IDX + 1))
  printf '%s[%d/%d]%s %s ... ' "$C_KEY" "$ST_STEP_IDX" "$ST_STEP_TOTAL" "$C_RESET" "$title"
  "$fn" || rc=$?
  case "$rc" in
    0)
      printf '%sOK%s\n' "$C_OK" "$C_RESET"
      ST_STEP_RESULTS+=("ok|${title}")
      ;;
    2)
      printf '%sSKIPPED%s\n' "$C_MUTED" "$C_RESET"
      ST_STEP_RESULTS+=("skip|${title}")
      ;;
    3)
      printf '%sWARN%s\n' "$C_WARN" "$C_RESET"
      ST_STEP_RESULTS+=("warn|${title}")
      ;;
    *)
      printf '%sFAILED%s\n' "$C_ERR" "$C_RESET"
      ST_STEP_RESULTS+=("fail|${title}")
      ;;
  esac
  return 0
}

st_report_summary() {
  local entry status _title ok=0 warn=0 fail=0 skip=0
  for entry in "${ST_STEP_RESULTS[@]-}"; do
    IFS='|' read -r status _title <<<"$entry"
    case "$status" in
      ok) ok=$((ok + 1)) ;;
      warn) warn=$((warn + 1)) ;;
      skip) skip=$((skip + 1)) ;;
      fail) fail=$((fail + 1)) ;;
    esac
  done

  ui_hr
  if ((fail > 0)); then
    printf '%sCompleted with failures:%s %d ok, %d warned, %d skipped, %d failed — see the log.\n' \
      "$C_ERR" "$C_RESET" "$ok" "$warn" "$skip" "$fail"
  elif ((warn > 0)); then
    printf '%sCompleted with warnings:%s %d ok, %d warned, %d skipped — details in the log.\n' \
      "$C_WARN" "$C_RESET" "$ok" "$warn" "$skip"
  else
    printf '%sAll steps completed:%s %d applied, %d skipped.\n' "$C_OK" "$C_RESET" "$ok" "$skip"
  fi
  ui_kv "Backups" "$ST_RUN_BACKUP_DIR"
  ui_kv "Log" "$ST_LOG_FILE"
  ui_kv "Rollback" "menu option [4], or: --rollback"
  printf '%sNo daemons or cron jobs were installed — nothing stays running.%s\n' "$C_MUTED" "$C_RESET"
}

_optimize_show_plan() {
  ui_kv "Profile" "${ST_PROFILE} (${ST_PROFILE_SOURCE})"
  if ((ST_EXPECTED_USERS > 0)); then
    ui_kv "Capacity" "${ST_EXPECTED_USERS} expected users (conntrack sized from users; buffers from RAM tier ${ST_TIER})"
  else
    ui_kv "Capacity tier" "${ST_TIER} — up to ${ST_TIER_USERS} concurrent users"
  fi
  if profile_wants_forwarding; then
    ui_kv "Conntrack" "${ST_CONNTRACK} entries (~$(tier_conntrack_ram_mb) MB kernel RAM worst case)"
  fi
  ui_kv "Socket buffers" "up to ${ST_BUF_MB} MB per socket"
  ui_kv "Congestion" "BBR when the kernel supports it, else cubic"

  local warn
  warn="$(capacity_warning)"
  if [[ -n $warn ]]; then
    printf '  %sCapacity warning:%s %s\n' "$C_WARN" "$C_RESET" "$warn"
    log_info "capacity warning: ${warn}"
  fi
}

# _optimize_run WITH_DNS WITH_SWAP WITH_LIMITS WITH_EXTRAS  (each 0/1)
_optimize_run() {
  local with_dns="$1" with_swap="$2" with_limits="$3" with_extras="$4"
  ST_STEP_RESULTS=()
  ST_STEP_IDX=0
  ST_STEP_TOTAL=$((1 + with_dns + with_swap + with_limits + with_extras))
  ui_hr
  st_run_step "Kernel network tuning (sysctl, tier ${ST_TIER})" sysctl_apply
  ((with_limits)) && st_run_step "File-descriptor limits (nofile)" limits_apply
  ((with_extras)) && st_run_step "Journald cap & NTP" extras_apply
  ((with_swap)) && st_run_step "Swap file" swap_apply
  ((with_dns)) && st_run_step "DNS (${ST_DNS1} / ${ST_DNS2})" dns_apply
  st_report_summary
  _offer_service_restart
  config_set last_profile "$ST_PROFILE"
  config_set last_tier "$ST_TIER"
  return 0
}

# _offer_service_restart — running services keep their old nofile limit
# until restarted; offer to restart detected VPN workloads (interactive),
# or just say so honestly (batch).
_offer_service_restart() {
  ((ST_LIMITS_CHANGED)) || return 0

  local containers=''
  if has_cmd docker; then
    # grep exit 1 (no match) is a normal outcome here, not an error.
    containers="$(docker ps --format '{{.Names}}' 2>/dev/null |
      grep -iE 'marzban|pg[-_]?node|pasarguard|x-?ui|xray|hiddify|sing-?box|hysteria|wg' || true)"
  fi

  if ((ST_OPT_BATCH)); then
    if [[ -n $containers ]]; then
      printf '%sNote:%s restart these containers so they pick up the new nofile limit:\n  %s\n' \
        "$C_WARN" "$C_RESET" "$(tr '\n' ' ' <<<"$containers")"
    fi
    return 0
  fi

  local name
  for name in $containers; do # global IFS splits on newlines — one name per entry
    if ui_confirm "Restart container '${name}' now so it picks up the new limits?"; then
      if docker restart "$name" >/dev/null 2>>"$ST_LOG_FILE"; then
        printf '%sRestarted:%s %s\n' "$C_OK" "$C_RESET" "$name"
      else
        log_warn "Could not restart ${name}."
      fi
    fi
  done

  local svc
  for svc in xray x-ui sing-box hysteria-server; do
    if has_cmd systemctl && systemctl is-active --quiet "$svc" 2>/dev/null; then
      if ui_confirm "Restart service '${svc}' now so it picks up the new limits?"; then
        if systemctl restart "$svc" 2>>"$ST_LOG_FILE"; then
          printf '%sRestarted:%s %s\n' "$C_OK" "$C_RESET" "$svc"
        else
          log_warn "Could not restart ${svc}."
        fi
      fi
    fi
  done
  return 0
}

quick_optimize() {
  ui_logo
  ui_title "Quick Optimize"
  detect_stack
  profile_resolve_auto
  tier_compute

  printf 'The base layer always optimizes the whole server; the detected profile\n'
  printf 'only adds specialised tuning on top of it.\n'
  ui_hr
  _optimize_show_plan
  ui_hr

  local with_dns=0
  if dns_select_menu; then
    with_dns=1
  fi

  printf '\n'
  if ! ui_confirm "Apply the plan above?"; then
    ui_pause
    return 0
  fi
  _optimize_run "$with_dns" 1 1 1
  ui_pause
}

# _apply_cli_profile_tier — resolve profile/tier honouring --profile/--tier
# overrides; invalid values die with a clear message. Shared by auto+dry-run.
_apply_cli_profile_tier() {
  if [[ -n $ST_AUTO_PROFILE ]]; then
    case "$ST_AUTO_PROFILE" in
      general | vpn-node | wireguard | panel | full)
        ST_PROFILE="$ST_AUTO_PROFILE"
        ST_PROFILE_SOURCE='cli'
        ;;
      *) die "Invalid --profile '${ST_AUTO_PROFILE}' (general|vpn-node|wireguard|panel|full)." ;;
    esac
  else
    profile_resolve_auto
  fi

  if [[ -n $ST_AUTO_USERS && ! $ST_AUTO_USERS =~ ^[0-9]+$ ]]; then
    die "Invalid --users '${ST_AUTO_USERS}' (expected a number)."
  fi

  tier_compute
  if [[ -n $ST_AUTO_TIER ]]; then
    case "$ST_AUTO_TIER" in
      S | M | L | XL)
        tier_set "$ST_AUTO_TIER"
        capacity_apply_users # a manual tier must not silently drop the users model
        ;;
      *) die "Invalid --tier '${ST_AUTO_TIER}' (S|M|L|XL)." ;;
    esac
  fi
}

# auto_optimize — the non-interactive flow behind --auto. No prompts: DNS is
# only touched when --dns was given.
auto_optimize() {
  detect_stack
  _apply_cli_profile_tier

  local with_dns=0
  if [[ -n $ST_AUTO_DNS ]]; then
    dns_resolve_cli "$ST_AUTO_DNS" ||
      die "Invalid --dns '${ST_AUTO_DNS}' (provider name or ip1,ip2)."
    with_dns=1
  fi

  ui_title "Auto Optimize (non-interactive)"
  _optimize_show_plan
  _optimize_run "$with_dns" "$ST_AUTO_SWAP" "$ST_AUTO_LIMITS" "$ST_AUTO_EXTRAS"
}

# dry_run_optimize — --dry-run: show the plan and the exact sysctl diff,
# apply absolutely nothing.
dry_run_optimize() {
  detect_stack
  _apply_cli_profile_tier
  ui_title "Dry Run — nothing will be applied"
  _optimize_show_plan
  ui_hr
  sysctl_dry_run
  printf '\nA real run would also cover: nofile limits, journald cap & NTP, swap%s.\n' \
    "$([[ -n $ST_AUTO_DNS ]] && printf ', DNS')"
}

custom_optimize() {
  ui_logo
  ui_title "Custom Optimize"
  detect_stack
  profile_resolve_auto
  local suggested="$ST_PROFILE"

  printf '%s[Workload profile]%s suggested: %s (%s)\n' \
    "$C_TITLE" "$C_RESET" "$suggested" "$ST_PROFILE_SOURCE"
  ui_menu_item 1 "general" "complete general-purpose tuning"
  ui_menu_item 2 "vpn-node" "Xray node (marzban-node / pg-node / x-ui)"
  ui_menu_item 3 "wireguard" "WireGuard host"
  ui_menu_item 4 "panel" "Marzban/Pasarguard panel host"
  ui_menu_item 5 "full" "everything with best-practice defaults"
  local choice
  read -rp "Select [Enter=suggested]: " choice || return 0
  case "${choice:-}" in
    1) ST_PROFILE='general' ;;
    2) ST_PROFILE='vpn-node' ;;
    3) ST_PROFILE='wireguard' ;;
    4) ST_PROFILE='panel' ;;
    5) ST_PROFILE='full' ;;
    *) ST_PROFILE="$suggested" ;;
  esac
  ST_PROFILE_SOURCE='manual'

  tier_compute
  local tier_choice
  read -rp "Capacity tier — auto picked ${ST_TIER} (up to ${ST_TIER_USERS} users). Override [S/M/L/XL, Enter=keep]: " tier_choice || tier_choice=''
  case "${tier_choice^^}" in
    S | M | L | XL)
      tier_set "${tier_choice^^}"
      config_set capacity_tier "${tier_choice^^}"
      ;;
  esac

  local users_in
  read -rp "Expected concurrent users [Enter=size by RAM, 0=reset saved value]: " users_in || users_in=''
  if [[ $users_in =~ ^[0-9]+$ ]]; then
    config_set expected_users "$users_in"
  fi
  capacity_apply_users

  ui_hr
  _optimize_show_plan
  ui_hr

  if ! ui_confirm_yes "Apply sysctl kernel tuning? (the core step)"; then
    printf 'Nothing to do without the sysctl step.\n'
    ui_pause
    return 0
  fi
  local with_swap=0 with_limits=0 with_extras=0 with_dns=0
  ui_confirm_yes "Raise file-descriptor limits?" && with_limits=1
  ui_confirm_yes "Cap journald disk usage and enable NTP?" && with_extras=1
  ui_confirm_yes "Create a swap file if none exists?" && with_swap=1
  if dns_select_menu; then
    with_dns=1
  fi

  printf '\n'
  if ! ui_confirm "Apply now?"; then
    ui_pause
    return 0
  fi
  _optimize_run "$with_dns" "$with_swap" "$with_limits" "$with_extras"
  ui_pause
}

# ------------------------- src/menu.sh -------------------------
# ============================================================================
# menu.sh — interactive main menu and sub-screens.
# The dashboard must render instantly: everything network-bound is cached
# (public IP is fetched at most once per process, in utils.sh).
# ============================================================================

menu_dashboard() {
  ui_logo
  ui_kv "OS" "$(os_pretty_name)"
  ui_kv "Kernel" "$(kernel_release)"
  ui_kv "RAM" "$(mem_total_mb) MB · $(cpu_cores) core(s)"
  ui_kv "Public IPv4" "$(net_public_ip4)"
  ui_kv "TCP" "cc=$(sysctl_get net.ipv4.tcp_congestion_control) · qdisc=$(sysctl_get net.core.default_qdisc)"
  ui_kv "Detected" "$(detect_summary)"
  ui_hr
}

menu_rollback() {
  ui_logo
  ui_title "Rollback"
  local run
  run="$(manifest_latest_run)"
  if [[ -z $run ]]; then
    printf 'No recorded changes yet — nothing to roll back.\n'
    ui_pause
    return 0
  fi
  printf 'Latest recorded run: %s%s%s\n' "$C_ACCENT" "$run" "$C_RESET"
  printf 'This restores every file that run modified and removes files it created.\n'
  ui_hr
  if ui_confirm "Revert all changes from this run?"; then
    rollback_latest
  fi
  ui_pause
}

menu_settings() {
  local choice
  while true; do
    ui_logo
    ui_title "Settings & Maintenance"
    ui_kv "Version" "$ST_VERSION"
    ui_kv "Config file" "$ST_CONFIG_FILE"
    ui_kv "Log file" "$ST_LOG_FILE"
    ui_kv "Backups" "$ST_BACKUP_DIR"
    ui_kv "Recorded changes" "$(manifest_entry_count)"
    ui_kv "Saved profile" "$(config_get last_profile 'none yet') / tier $(config_get last_tier '-')"
    ui_hr
    ui_menu_item 1 "Install 'st' command" "run 'st' instead of the long one-liner"
    ui_menu_item 2 "Check for updates" "self-update from the latest release"
    ui_menu_item 0 "Back"
    ui_hr
    read -rp "Select: " choice || return 0
    case "${choice:-}" in
      1)
        st_self_install || log_warn "Install did not complete."
        ui_pause
        ;;
      2)
        st_self_update || log_warn "Update did not complete."
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

main_menu() {
  detect_stack
  local choice
  while true; do
    menu_dashboard
    ui_menu_item 1 "Quick Optimize" "full base layer + auto-detected profile (recommended)"
    ui_menu_item 2 "Custom Optimize" "pick profile and modules manually"
    ui_menu_item 3 "System Status" "full report"
    ui_menu_item 4 "Rollback" "undo the latest recorded run"
    ui_menu_item 5 "Security" "UFW / fail2ban / SSH hardening (optional)"
    ui_menu_item 6 "Network & VPN tools" "ping matrix, MSS clamp, audits"
    ui_menu_item 7 "Settings" "paths, config, manifest"
    ui_menu_item 0 "Exit"
    ui_hr
    # EOF (e.g. closed stdin) simply exits the menu.
    read -rp "Select: " choice || {
      printf '\n'
      return 0
    }
    case "${choice:-}" in
      1) quick_optimize ;;
      2) custom_optimize ;;
      3) show_status ;;
      4) menu_rollback ;;
      5) security_menu ;;
      6) tools_menu ;;
      7) menu_settings ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/99-main.sh -------------------------
# ============================================================================
# 99-main.sh — CLI argument parsing and the program entrypoint.
# This file MUST be last in the build order (see build.sh SOURCES).
# ============================================================================

usage() {
  cat <<EOF
${ST_NAME} v${ST_VERSION} — Linux server optimization toolkit
${ST_REPO_URL}

Usage: server-tools.sh [OPTIONS]   (installed: st [OPTIONS])

Actions (no action starts the interactive menu):
  --status              Print the full system status report and exit
  --auto                Non-interactive optimize: base layer + detected profile
  --dry-run             Show the plan and exact sysctl diff, apply NOTHING
  --report              Print + save a plain-text support report
  --rollback            Revert the latest recorded run and exit
  --install             Install as the 'st' command (/usr/local/bin/st)
  --update              Self-update from the latest GitHub release

Options for --auto:
  --profile NAME        general | vpn-node | wireguard | panel | full
  --tier T              Capacity tier: S | M | L | XL (default: by RAM)
  --users N             Expected concurrent users — sizes conntrack from the
                        real user count instead of RAM (with a RAM warning)
  --dns VALUE           Provider (cloudflare|google|quad9|opendns|shecan)
                        or custom "primary,secondary" (skipped when omitted)
  --no-swap             Skip the swap step
  --no-limits           Skip the nofile limits step
  --no-extras           Skip the journald/NTP step

General options:
  --no-color            Disable colored output (NO_COLOR env also honoured)
  --debug               Verbose logging to console and log file
  -v, --version         Print version and exit
  -h, --help            Show this help

Example (fleet provisioning):
  st --auto --profile vpn-node --tier L --dns cloudflare
EOF
}

_need_value() { # _need_value OPTION VALUE
  if [[ -z ${2:-} ]]; then
    printf 'Missing value for %s\n' "$1" >&2
    exit 2
  fi
}

main() {
  local action="menu"
  while (($# > 0)); do
    case "$1" in
      -v | --version)
        printf '%s %s\n' "$ST_NAME" "$ST_VERSION"
        return 0
        ;;
      -h | --help)
        usage
        return 0
        ;;
      --status) action="status" ;;
      --rollback) action="rollback" ;;
      --auto) action="auto" ;;
      --dry-run) action="dryrun" ;;
      --report) action="report" ;;
      --install) action="install" ;;
      --update) action="update" ;;
      --profile)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_PROFILE="$1"
        ;;
      --tier)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_TIER="${1^^}"
        ;;
      --users)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_USERS="$1"
        ;;
      --dns)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_DNS="$1"
        ;;
      --no-swap) ST_AUTO_SWAP=0 ;;
      --no-limits) ST_AUTO_LIMITS=0 ;;
      --no-extras) ST_AUTO_EXTRAS=0 ;;
      --no-color) ST_OPT_NO_COLOR=1 ;;
      --debug) ST_OPT_DEBUG=1 ;;
      *)
        printf 'Unknown option: %s\n\n' "$1" >&2
        usage >&2
        exit 2
        ;;
    esac
    shift
  done

  ui_detect_terminal
  require_root
  log_init
  state_init
  config_load
  log_info "${ST_NAME} v${ST_VERSION} started (run ${ST_RUN_ID}, action=${action})"

  case "$action" in
    status)
      ST_OPT_BATCH=1
      detect_stack
      show_status
      ;;
    rollback)
      ST_OPT_BATCH=1
      rollback_latest
      ;;
    auto)
      ST_OPT_BATCH=1
      auto_optimize
      ;;
    dryrun)
      ST_OPT_BATCH=1
      dry_run_optimize
      ;;
    report)
      ST_OPT_BATCH=1
      detect_stack
      tools_report
      ;;
    install)
      ST_OPT_BATCH=1
      st_self_install
      ;;
    update)
      ST_OPT_BATCH=1
      st_self_update
      ;;
    menu)
      main_menu
      ;;
  esac

  log_info "${ST_NAME} finished (run ${ST_RUN_ID})"
}

main "$@"
